"You are the Consortium. Builder → \"Build\" (F1) → \"Concrete barrier\" → LMB at the marker. The section faces the enemy by itself.":"Bạn là Liên minh. Kỹ sư → “Xây dựng” (F1) → “Rào bê tông” → chuột trái tại dấu. Đoạn tường tự quay về phía địch.",
"Place the second section at the \"NEXT TO IT\" marker — it snaps to the first (Shift+LMB for several). The wall stops bullets, shells and vehicles.":"Đặt đoạn thứ hai tại dấu “NỐI TIẾP” — nó gắn vào đoạn đầu (Shift+chuột trái để đặt nhiều). Tường chặn đạn, đạn pháo và xe.",
"\"Build\" → \"Repair post\" → LMB at the marker. It repairs vehicles, buildings and infantry within 26 m — put it behind the barriers.":"“Xây dựng” → “Trạm sửa chữa” → chuột trái tại dấu. Trạm sửa xe, công trình và bộ binh trong 26 m — đặt sau rào chắn.",
"The tank is damaged (35 %). Select it (LMB) and RMB next to the repair post — green beams fix it.":"Xe tăng bị hỏng (35 %). Chọn nó (chuột trái) và chuột phải cạnh trạm sửa chữa — tia xanh sẽ sửa nó.",
"Field repair: idle Consortium builders take on damaged vehicles within 70 m and buildings within 80 m by themselves — 1.3× faster. Just watch.":"Sửa dã chiến: kỹ sư Liên minh rảnh sẽ tự sửa xe hỏng trong 70 m và công trình trong 80 m — nhanh gấp 1.3 lần. Cứ xem.",
"Bosses unlock at 12:00 (time is skipped here). A factory is required — it is already built. Builder → \"Build\" → the boss plant → LMB at the marker.":"Trùm mở khóa lúc 12:00 (bài học tua nhanh). Cần nhà máy — đã có sẵn. Kỹ sư → “Xây dựng” → xưởng trùm → chuột trái tại dấu.",
"The plant is going up. Then click it → order the boss (instant in the lesson; ~100 s in battle). One per army; the enemy gets a radio warning.":"Xưởng đang xây. Sau đó nhấp vào nó → đặt trùm (ngay lập tức trong bài học; ~100 giây trong trận). Mỗi quân một chiếc; địch nhận cảnh báo qua bộ đàm.",
"Huge hull (bar at the top), very slow, slow to turn. Select it (LMB) and RMB on the \"HERE\" marker.":"Thân rất bền (thanh ở trên cùng), rất chậm, xoay chậm. Chọn nó (chuột trái) và chuột phải vào dấu “ĐẾN ĐÂY”.",
"Possess your boss: select it in strategy and press {0} (or \"▶ Possess\"). Outside camera, LMB — main weapon.":"Nhập vai trùm của bạn: chọn nó trong chế độ chiến thuật và nhấn {0} (hoặc “▶ Nhập vai”). Góc nhìn bên ngoài, chuột trái — vũ khí chính.",
"☰ → \"▤ Powers\" → \"✈ Carpet bombing\" (5 CP). The yellow strip shows where 10 bombs fall.":"☰ → “▤ Đòn đánh” → “✈ Ném bom rải thảm” (5 ĐCH). Dải vàng cho thấy nơi 10 quả bom rơi.",
"Tap ⟳ at the bottom — the strip turns 30°. The bomber flies along the arrow.":"Chạm ⟳ ở dưới — dải xoay 30°. Máy bay bay theo mũi tên.",
"Tap the \"TARGET\" marker — impact in 3.5 s. Or press on the target and drag to set the run.":"Chạm dấu “MỤC TIÊU” — trúng sau 3.5 giây. Hoặc ấn vào mục tiêu và kéo để chọn hướng bay.",
"☰ → \"▤ Powers\" → \"♨ Napalm\" (3 CP) → tap the marker. Burns 9 s, ignites methane.":"☰ → “▤ Đòn đánh” → “♨ Bom napalm” (3 ĐCH) → chạm dấu. Cháy 9 giây, đốt mê-tan.",
"In battle: 📡 on the right → \"Carpet\" or \"Napalm\". It lands where you look.":"Trong trận: 📡 bên phải → “Rải thảm” hoặc “Napalm”. Đòn rơi chỗ bạn nhìn.",
"You are at a lava lake. Use the stick to step onto its edge at the marker — feel the heat — and back off.":"Bạn đang ở hồ dung nham. Dùng cần điều khiển bước lên mép dung nham ở dấu — cảm nhận sức nóng — rồi lùi lại.",
"Ice: run across and try to stop — you slide.":"Băng: chạy qua và thử dừng lại — bị trượt.",
"Methane fog over the lake. Fire and blasts ignite it: a rocket or a grenade into the fog.":"Sương mê-tan trên hồ. Lửa và vụ nổ sẽ đốt nó: bắn tên lửa hoặc ném lựu đạn vào sương.",
"The rock hangar is cover: outside blasts do a third of the damage. Walk in.":"Nhà chứa trong đá là chỗ nấp: vụ nổ bên ngoài chỉ gây một phần ba sát thương. Đi vào.",
"You are the Swarm. Tap a builder → \"Build\" → \"Tunnel burrow\" → tap at the marker → \"Build\".":"Bạn là Bầy Đàn. Chạm kỹ sư → “Xây dựng” → “Hang đường hầm” → chạm tại dấu → “Xây”.",
"Tap the burrow → \"⛏ Dig the exit\" → tap the \"EXIT\" marker (up to 220 m).":"Chạm hang → “⛏ Đào lối ra” → chạm dấu “LỐI RA” (tới 220 m).",
"Tap a squad (or light vehicles) → \"⇣ Into tunnel\" on the card, or tap the burrow. Or \"Squads into the tunnel\" in the burrow panel.":"Chạm một đội (hoặc xe nhẹ) → “⇣ Vào hầm” trên thẻ, hoặc chạm vào hang. Hoặc “Đội vào hầm” trong bảng hang.",
"You are the Consortium. Builder → \"Build\" → \"Concrete barrier\" → tap at the marker → \"Build\".":"Bạn là Liên minh. Kỹ sư → “Xây dựng” → “Rào bê tông” → chạm tại dấu → “Xây”.",
"After \"Build\" the next section is offered right away — \"Build\" again (or tap the \"NEXT TO IT\" marker).":"Sau “Xây”, đoạn tiếp theo được gợi ý ngay — nhấn “Xây” lần nữa (hoặc chạm dấu “NỐI TIẾP”).",
"\"Build\" → \"Repair post\" → tap the marker → \"Build\". Repairs everything within 26 m.":"“Xây dựng” → “Trạm sửa chữa” → chạm dấu → “Xây”. Sửa mọi thứ trong 26 m.",
"The tank is damaged (35 %). Tap it, then tap next to the repair post — green beams fix it.":"Xe tăng bị hỏng (35 %). Chạm nó, rồi chạm cạnh trạm sửa chữa — tia xanh sẽ sửa nó.",
"Bosses unlock at 12:00 (skipped here). Builder → \"Build\" → the boss plant → tap the marker → \"Build\".":"Trùm mở khóa lúc 12:00 (đã tua nhanh). Kỹ sư → “Xây dựng” → xưởng trùm → chạm dấu → “Xây”.",
"The plant is going up. Then tap it → order the boss (instant here). One per army.":"Xưởng đang xây. Sau đó chạm nó → đặt trùm (ngay lập tức ở đây). Mỗi quân một chiếc.",
"Huge hull, very slow. Tap it, then tap the \"HERE\" marker.":"Thân rất bền, rất chậm. Chạm nó, rồi chạm dấu “ĐẾN ĐÂY”.",
"Possess your boss: tap it in strategy → \"▶ Possess\". Always allowed, even if \"Possession: vehicles\" is off.":"Nhập vai trùm của bạn: chạm nó trong chế độ chiến thuật → “▶ Nhập vai”. Luôn được phép, kể cả khi tắt “Nhập vai: Xe”.",
