"Napalm":"Napalm",
"A 12 m fire zone burns for 9 seconds: damage over time, suppression, smoke. After 2.5 s. Ignites methane.":"12 m olov zonasi 9 soniya yonadi: davomiy zarar, bostirish, tutun. 2.5 s dan keyin. Metanni yondiradi.",
