"🔥 Lava! Get off it":"🔥 Lava! Undan chiqing",
"Concrete barrier":"Beton toʻsiq",
"Consortium. 7 m wall section: stops bullets, shells and vehicles. Chain them (Shift+click).":"Konsorsium. 7 m devor boʻlagi: oʻq, snaryad va texnikani toʻxtatadi. Zanjir qilib qoʻying (Shift+klik).",
"Repair post":"Taʼmirlash posti",
"Consortium. Repairs vehicles, buildings and infantry within 26 m.":"Konsorsium. 26 m ichida texnika, bino va piyodalarni taʼmirlaydi.",
"Tunnel burrow":"Tunnel ini",
"Swarm. Tunnel entrance: then \"Dig the exit\" to a point up to 220 m away — infantry travels underground.":"Gala. Tunnelga kirish: keyin «Chiqish qazish» bilan 220 m gacha nuqtaga — piyodalar yer ostidan oʻtadi.",
"Tunnel exit":"Tunnel chiqishi",
"Swarm. Tunnel exit. Destroy it and the tunnel collapses.":"Gala. Tunnel chiqishi. Uni buzsangiz, tunnel qulaydi.",
"Disabled":"Oʻchirilgan",
"Appears by itself when the tunnel breaks through":"Tunnel ochilganda oʻzi paydo boʻladi",
"Only for {0}":"Faqat {0} uchun",
"Limit: {0}":"Chegara: {0}",
"Swarm: builders can make a \"Tunnel burrow\" — dig an exit up to 220 m away and move infantry underground behind enemy lines. Swarm squads are cheaper and heal out of combat.":"Gala: muhandislar «Tunnel ini» quradi — 220 m gacha chiqish qazib, piyodalarni yer ostidan dushman orqasiga oʻtkazing. Gala otryadlari arzonroq va jangdan tashqarida tuzaladi.",
"Consortium: builders place \"Concrete barriers\" and a \"Repair post\"; turrets are cheaper and tougher, builders repair vehicles on their own.":"Konsorsium: muhandislar «Beton toʻsiq» va «Taʼmirlash posti» qoʻyadi; turellar arzonroq va mustahkamroq, muhandislar texnikani oʻzi taʼmirlaydi.",
"At: ":"Joyi: ",
"cover":"pana",
"repairs within 26 m":"26 m ichida taʼmirlaydi",
"tunnel exit":"tunnel chiqishi",
"digging the exit":"chiqish qazilmoqda",
"tunnel open":"tunnel ochiq",
"no exit yet":"chiqish hali yoʻq",
"Spot is taken":"Joy band",
"Rocks in the way":"Qoyalar xalaqit beradi",
"A barrier stops bullets and vehicles. Next to an existing section a new one snaps on — that is how you build a wall.":"Toʻsiq oʻq va texnikani toʻxtatadi. Mavjud boʻlak yonida yangisi ulanib qoladi — devor shunday quriladi.",
"Automatic machine gun. Can be manned. Consortium: cheaper ({0}), toughness ×{1}, damage ×{2}.":"Avtomatik pulemyot. Boshqarish mumkin. Konsorsium: arzonroq ({0}), mustahkamlik ×{1}, zarar ×{2}.",
"Consortium builders repair nearby vehicles and buildings on their own (up to 70–80 m), 1.3× faster.":"Konsorsium muhandislari yaqindagi texnika va binolarni oʻzi taʼmirlaydi (70–80 m gacha), 1.3 marta tezroq.",
"The repair post fixes vehicles, buildings and infantry within 26 m — put it near the front, behind barriers.":"Taʼmirlash posti 26 m ichida texnika, bino va piyodalarni tuzatadi — uni front yaqiniga, toʻsiqlar ortiga qoʻying.",
