"Swarm. Pick a point up to 220 m away — the exit breaks through in 24 s. 10 s before, the enemy hears rumbling and sees dust.":"Gala. 220 m gacha nuqtani tanlang — chiqish 24 s da ochiladi. 10 s oldin dushman guvillashni eshitib, changni koʻradi.",
"Squads into the tunnel":"Otryadlar — tunnelga",
"Swarm. Squads within 70 m of the burrow (and selected ones) go through the tunnel. Or select squads and RMB/tap the burrow.":"Gala. Indan 70 m ichidagi (va tanlangan) otryadlar tunneldan oʻtadi. Yoki otryadlarni tanlab, inga oʻng klik/bosing.",
"Swarm only":"Faqat Gala",
"Needs a Tunnel burrow":"Tunnel ini kerak",
"Still being built":"Hali qurilmoqda",
"Exit already open":"Chiqish ochiq",
