"Too close to the HQ or a point — no digging here":"Shtab yoki nuqtaga juda yaqin — bu yerda qazilmaydi",
"Burrow ready: select it, press \"Dig the exit\", then pick the exit point.":"In tayyor: uni tanlang, «Chiqish qazish»ni bosing, soʻng chiqish nuqtasini.",
"Swarm: infantry and drones heal out of combat — after 5 s without damage, 4% per second. Pull the wounded back.":"Gala: piyodalar va dronlar jangdan tashqarida tuzaladi — zararsiz 5 s dan keyin, soniyasiga 4%. Yaradorlarni orqaga torting.",
