"ready to assemble":"yigʻishga tayyor",
"The \"Assembly hall\" is unlocked: it builds the super-heavy tank \"Bastion\" — one per army. Its weak spot is the rear.":"«Yigʻuv sexi» ochildi: unda oʻta ogʻir tank «Bastion» yigʻiladi — har armiyaga bitta. Uning zaif joyi — orqasi.",
"The \"Incubator\" is unlocked: it grows the \"Reaper\" walker — one per army. Its weak spot is the glowing core underneath.":"«Inkubator» ochildi: unda «Oʻroqchi» yuruvchi mashinasi oʻsadi — har armiyaga bitta. Uning zaif joyi — pastdagi yonib turgan yadro.",
"Versus the \"Bastion\": hit it from the rear (nearly double damage), use air strikes, or tunnel behind it.":"«Bastion»ga qarshi: orqasidan uring (zarar deyarli ikki baravar), havo zarbasi bering yoki orqasiga tunnel qazing.",
"Versus the \"Reaper\": shoot the glowing core from below (nearly double damage) and use air strikes.":"«Oʻroqchi»ga qarshi: yonib turgan yadroga pastdan oting (zarar deyarli ikki baravar) va havo zarbasi bering.",
