"MY SQUADS":"OTRYADLARIM",
"Veterancy carries over between battles. A squad earns XP (infantry 1, building 2, vehicle 3), levels, stars and perks. Veterans deploy first in a new battle. A lost squad loses everything and joins the Fallen.":"Faxriylik janglar orasida saqlanadi. Otryad tajriba toʻplaydi (piyoda 1, bino 2, texnika 3), daraja, yulduz va perklar oladi. Yangi jangda faxriylar birinchi safga turadi. Halok boʻlgan otryad hammasini yoʻqotib, «Halok boʻlganlar»ga oʻtadi.",
