"the Verdan is angry!":"verdan gʻazablandi!",
"Verdan":"Verdan",
"destroyed, a spray of green sap":"yoʻq qilindi, yashil sharbat sachradi",
"ANGRY":"GʻAZABDA",
"A Verdan! This plant bites!":"Verdan! Bu oʻt tishlaydi!",
"Don't touch the plants — they get angry!":"Oʻsimliklarga tegmang — ular gʻazablanadi!",
"Biomes and anomalies":"Biomlar va anomaliyalar",
"Green grass hides infantry, sharp biome borders, the Dislocation throws you to the antipode, Verdans are neutral until provoked":"Yashil oʻt piyodani yashiradi, biomlar chegarasi keskin, Siljish antipodga uloqtiradi, verdanlar tegmaguncha betaraf",
"GRASS":"OʻT",
"ACROSS":"CHEGARA ORTI",
"DISLOCATION":"SILJISH",
"VERDAN":"VERDAN",
"Green zone":"Yashil zona",
"Sharp border":"Keskin chegara",
"The meteor now has biomes: green grass, russet autumn, snow — with sharp borders. Walk to the \"GRASS\" marker. In the green zone grass hides infantry: enemies beyond 40 m cannot see you unless you fire.":"Endi meteoritda biomlar bor: yashil oʻt, malla kuz, qor — keskin chegaralar bilan. «OʻT» belgisiga boring. Yashil zonada oʻt piyodani yashiradi: oʻq uzmasangiz, 40 m dan naridagi dushman sizni koʻrmaydi.",
"Cross the border to the marker. In the Russet belt footsteps are louder (runners are heard 32 m away), in the White cap infantry is 15% slower and sight is ×0.7.":"Chegaradan belgigacha oʻting. Malla belbogʻda qadamlar balandroq (yuguruvchi 32 m dan eshitiladi), Oq qalpoqda piyoda 15% sekinroq, koʻrish esa ×0.7.",
"Second-wave anomalies. The Dislocation — dust falls upwards. Step in: the sky portal takes you and ~5 s later you exit at the antipode (both teams see the exit). Also: Mosaic (pixels, spread), Geyser (freeze), Draught (pushes), Muffler (no radio). A bolt (E) or a grenade discharges an anomaly.":"Ikkinchi toʻlqin anomaliyalari. Siljish — chang yuqoriga tushadi. Ichiga kiring: osmon portali sizni olib ketadi va ~5 s dan keyin antipodda chiqasiz (chiqishni ikkala jamoa koʻradi). Yana: Mozaika (piksellar, tarqoqlik), Geyzer (muzlatish), Yelvizak (itaradi), Jimlatgich (aloqa yoʻq). Bolt (E) yoki granata anomaliyani zaryadsizlantiradi.",
"A Verdan is a living alien plant. It is neutral until you touch it or come close, but dangerous to both factions. This one is a Sporecap: destroy it from range (LMB) without walking into the spore cloud. Fire burns Verdans harder.":"Verdan — tirik oʻzga sayyora oʻsimligi. Tegmaguningizcha yoki yaqinlashmaguningizcha betaraf, lekin ikkala fraksiya uchun xavfli. Bu — Sporaqalpoq: uni uzoqdan yoʻq qiling (chap klik), spora bulutiga kirmang. Olov verdanlarni kuchliroq kuydiradi.",
"The meteor now has biomes with sharp borders. Use the stick to walk to the \"GRASS\" marker. Grass hides infantry beyond 40 m unless you fire.":"Endi meteoritda keskin chegarali biomlar bor. Joystik bilan «OʻT» belgisiga boring. Oʻq uzmasangiz, oʻt piyodani 40 m dan narida yashiradi.",
"Cross the border to the marker. Autumn — louder steps, snow — slower and worse sight.":"Chegaradan belgigacha oʻting. Kuz — qadamlar balandroq, qor — sekinroq va koʻrish yomonroq.",
"The Dislocation — dust falls upwards. Step in: it lifts you to the sky and ~5 s later drops you at the antipode. The ⏏ button near an anomaly throws a bolt to discharge it.":"Siljish — chang yuqoriga tushadi. Ichiga kiring: u osmonga koʻtaradi va ~5 s dan keyin antipodga tashlaydi. Anomaliya yonidagi ⏏ tugmasi — bolt otib, uni zaryadsizlantirish.",
"A Verdan is neutral until you come close. Destroy the Sporecap from range — shoot.":"Verdan yaqinlashmaguningizcha betaraf. Sporaqalpoqni uzoqdan yoʻq qiling — oting.",
