"No other squads":"Boshqa otryadlar yoʻq",
"Mode button at the top right: tap — next (Strategist → Commander → Shooter), hold — pick":"Yuqori oʻngdagi rejim tugmasi: bosish — keyingisi (Strateg → Qoʻmondon → Otuvchi), ushlab turish — tanlash",
"{0} cycles: Strategist → Commander → Shooter · Alt+1/2/3 — straight to a mode":"{0} — aylana: Strateg → Qoʻmondon → Otuvchi · Alt+1/2/3 — toʻgʻridan-toʻgʻri rejimga",
"Mode: {0}. Click or {1} — next; hold or RMB — pick; Alt+1/2/3 — direct":"Rejim: {0}. Klik yoki {1} — keyingisi; ushlab turish yoki oʻng klik — tanlash; Alt+1/2/3 — toʻgʻridan-toʻgʻri",
"Box":"Ramka",
"All army":"Butun armiya",
"Builder":"Muhandis",
"possess the selection (nothing selected — to battle)":"tanlanganni boshqarish (hech narsa tanlanmagan — jangga)",
"mode cycle: Strategist → Commander → Shooter · Alt+1/2/3 — direct":"rejim aylanasi: Strateg → Qoʻmondon → Otuvchi · Alt+1/2/3 — toʻgʻridan-toʻgʻri",
"strategy (the same key there possesses the selection)":"strategiya (u yerda oʻsha tugma — tanlanganni boshqarish)",
"strategy (cycle: Strategist → Commander → Shooter; P / Alt+2 — straight to Commander)":"strategiya (aylana: Strateg → Qoʻmondon → Otuvchi; P / Alt+2 — toʻgʻri Qoʻmondonga)",
"\"Commander\" on phone (off — hide)":"Telefonda «Qoʻmondon» (oʻchiq — yashirish)",
"One button, three modes: Strategist → Commander → Shooter. Top view of one squad, click orders, 4 abilities, squad switching, diving into the shooter and back":"Bitta tugma — uchta rejim: Strateg → Qoʻmondon → Otuvchi. Bitta otryadga yuqoridan qarash, klik bilan buyruqlar, 4 qobiliyat, otryad almashtirish, Otuvchiga shoʻngʻish va qaytish",
"One button, three modes in a cycle: Strategist → Commander → Shooter. Press {0} or the mode button below (next to \"▶ Possess\") to get to Commander. Straight there — P or Alt+2.":"Bitta tugma — aylanada uchta rejim: Strateg → Qoʻmondon → Otuvchi. Qoʻmondonga oʻtish uchun {0} yoki pastdagi rejim tugmasini bosing («▶ Boshqarish» yonida). Toʻgʻridan-toʻgʻri — P yoki Alt+2.",
"Switch squads: {0} — the next one (closest to the fight first), a card on the left or the middle mouse button on a squad. The previous squad keeps its order.":"Otryad almashtiring: {0} — keyingisi (avval jangga eng yaqini), chapdagi kartochka yoki otryadga oʻrta tugma. Oldingi otryad buyrugʻini davom ettiradi.",
"Next on the ladder is the Shooter: {0} or the mode button. Also: double LMB on a trooper or F. Wheel all the way in — third person.":"Zinapoyada keyingisi — Otuvchi: {0} yoki rejim tugmasi. Yana: jangchiga ikki marta chap klik yoki F. Gʻildirakni oxirigacha ichkariga — uchinchi shaxs.",
"{0} in the shooter cycles on to the Strategist. Straight to Commander — P or Alt+2 (or hold the mode button and pick ⌖). Squad veterancy is kept: menu → \"My squads\".":"Otuvchi rejimida {0} aylana boʻyicha Strategga olib boradi. Toʻgʻri Qoʻmondonga — P yoki Alt+2 (yoki rejim tugmasini ushlab turib ⌖ ni tanlang). Faxriylik saqlanadi: menyu → «Otryadlarim».",
"The mode button at the top right: tap — next mode in the cycle (Strategist → Commander → Shooter). Tap it to get to Commander ⌖. Hold — pick one of three.":"Yuqori oʻngdagi rejim tugmasi: bosish — aylanadagi keyingi rejim (Strateg → Qoʻmondon → Otuvchi). Qoʻmondon ⌖ ga oʻtish uchun bosing. Ushlab turish — uchtadan birini tanlash.",
"Tap another card on the left or ⇆ at the top — the next squad (closest to the fight first).":"Chapdagi boshqa kartochkani yoki tepadagi ⇆ ni bosing — keyingi otryad (avval jangga eng yaqini).",
"Tap the mode button \"▶ Fight\" — next on the ladder, the Shooter. Or double-tap a trooper of the squad.":"Rejim tugmasi «▶ Jangga»ni bosing — zinapoyada keyingisi, Otuvchi. Yoki otryad jangchisini ikki marta bosing.",
"Hold the mode button — three icons appear — pick ⌖ Commander. (A plain tap cycles on to the Strategist.) Veterancy is kept: menu → \"My squads\".":"Rejim tugmasini ushlab turing — uchta belgi chiqadi — ⌖ Qoʻmondonni tanlang. (Oddiy bosish aylana boʻyicha Strategga olib boradi.) Faxriylik saqlanadi: menyu → «Otryadlarim».",
