"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Oʻzimiznikilar baʼzan yordam soʻraydi: radio orqali ovoz, «ILTIMOS» kartochkasi va ✋ belgisi. Otryad qisib qoʻyilgan — uning yonidagi dushmanlarni yoʻq qiling. Mukofot: bazadan kapsulada jangchi, bagi kuzovidan qurol, oʻqchi oʻrni yoki orbitadan himoya. Xohlamasangiz — ✕ yoki eʼtibor bermang.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Faxriy razvedkachi «Boyqush» topshiriq taklif qiladi. Y — qabul (N — rad). ★ belgisiga boring, qoʻriqchilarni yoʻq qiling va uchuvchi yonida 3 s turing — u otryadingizga qoʻshiladi.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Front toʻxtadi — shtab burilishni taklif qiladi. Y — qabul. Yaqinda dushman boʻlmasa, retranslyatorni 8 s ushlang: dushman xaritasi 60 s koʻrinadi. Generator — dushman turellari 2 daq jim. Strategda — «Otryadga topshirish». Dushman ham shunday qila oladi: ⚠ ni kuzating.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Oʻzimiznikilar yordam soʻraydi: «ILTIMOS» kartochkasi va ✋ belgisi. Qisib qoʻyilgan otryad yonidagi dushmanlarni yoʻq qiling — mukofot oling. ✕ — oʻtkazish.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"Qahramon «Boyqush» topshiriq taklif qiladi — «Qabul»ni bosing. ★ ga boring, qoʻriqchilarni yoʻq qiling, uchuvchi yonida turing.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Front toʻxtadi — «Qabul»ni bosing va retranslyatorni 8 s ushlang: dushman xaritasi bir daqiqaga ochiladi.",
"Pod redeploy from the base: {0} m — through the sky portal":"Bazadan kapsulada koʻchirish: {0} m — osmon portali orqali",
"Pod away from the base! Hold on — exit over the target.":"Kapsula bazadan chiqdi! Mahkam turing — chiqish nishon ustida.",
"Landed at the objective!":"Nishon yoniga tushdik!",
"LAUNCH FROM BASE":"BAZADAN UCHIRISH",
"LANDING":"QOʻNISH",
"REDEPLOY":"KOʻCHIRISH",
"Steel fluff stuck to you — corrodes armour −2/s. Stand still 3 s out of combat or find an engineer":"Poʻlat momiq yopishdi — zirhni yemiradi −2/s. Jangdan tashqarida 3 s turing yoki muhandisga boring",
"An engineer brushed the fluff off":"Muhandis momiqni tozaladi",
"The fluff fell off — armour is safe":"Momiq toʻkildi — zirh butun",
"The firefly swarm scattered by the blast":"Yaltiroqlar toʻdasi portlashdan tarqaldi",
"STEEL FLUFF −2/s · stand still 3 s or find an engineer":"POʻLAT MOMIQ −2/s · 3 s turing yoki muhandisga boring",
"Lefty's convoy is ready: two Jackals. Stay close — they wait for you":"Chapaqay karvoni tayyor: ikkita «Chiyaboʻri». Yaqin turing — sizni kutishadi",
"The convoy is waiting for you":"Karvon sizni kutmoqda",
"Ambush! Cover the Jackals!":"Pistirma! «Chiyaboʻri»larni yopib turing!",
"the convoy made it ({0} of 2)! +2 CP, +150 ore, the Jackals are yours":"karvon yetib keldi ({0} / 2)! +2 QO, +150 ruda, «Chiyaboʻri»lar sizniki",
"The parts are delivered! Thanks, commander.":"Detallar yetkazildi! Rahmat, qoʻmondon.",
