"Fluff in the air — keep out of the meadow and away from the infected!":"Havoda momiq — oʻtloqqa kirmang va zararlanganlardan uzoq turing!",
"fluff blown away, dormant for 25 s · +0.5 CP":"momiq uchib ketdi, oʻtloq 25 s uxlaydi · +0.5 QO",
"My crew is hauling parts to point {0}. Escort the column — there may be an ambush.":"Yigitlarim detallarni {0} nuqtasiga olib ketyapti. Karvonni kuzatib boring — yoʻlda pistirma boʻlishi mumkin.",
