"Main battle tank: cannon and MG. Consortium \"Bulldog\" is tougher, Swarm \"Spider\" is faster.":"Asosiy tank: toʻp va pulemyot. Konsorsiumning «Buldog»i mustahkamroq, Galaning «Oʻrgimchak»i tezroq.",
