"Drones":"Dronlar",
"Longer, faster jetpacks for all infantry.":"Butun piyodalar uchun uzoqroq va tezroq jetpaklar.",
"Extractors mine more ore.":"Ekstraktorlar koʻproq ruda qazib oladi.",
"Army-wide levels: less damage taken / more damage dealt.":"Butun qoʻshin uchun darajalar: kamroq zarar olish / koʻproq zarar berish.",
"Levels":"Darajalar",
"Base":"Baza",
"Heart of the base: squads, engineers, pods, research. Lose it and you lose.":"Bazaning yuragi: otryadlar, muhandislar, kapsulalar, tadqiqotlar. Uni yoʻqotsangiz — magʻlubiyat.",
"Produces: ":"Ishlab chiqaradi: ",
"Launch pad":"Uchirish maydonchasi",
"A silo next to the HQ: pods, supply crates and bombers launch from here through the sky portal. Nothing can be built on it.":"Shtab yonidagi shaxta: kapsulalar, taʼminot qutilari va bombardimonchilar shu yerdan osmon portali orqali uchadi. Unda qurib boʻlmaydi.",
"Economy":"Iqtisod",
"Key building":"Asosiy bino",
"Building":"Bino",
"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"Zaif joy — orqa qism (dvigatel): zarar ×{0}. Toʻp, 2 pulemyot minorasi, raketa kassetasi; juda sekin buriladi — yonidan aylanib oʻting.",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"Zaif joy — qorin ostidagi yorqin yadro: pastdan zarar ×{0}. Buzilish nuri va hududiy tepish; toʻsiqlardan hatlab oʻtadi — masofa saqlang, toʻplanib turmang.",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"Qarshi: bombalar va artilleriya (×{0}), raketalar (×{1}), gilam bombardimoni; oʻqlar deyarli taʼsir qilmaydi (×{2}).",
"Faction":"Fraksiya",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"Tez mashinalar, dron toʻdalari, tunnellar va regeneratsiya. Piyodalar yengilroq, lekin tezroq; toʻplar va relsotronlar kuchliroq uradi.",
"Heavy power-armoured infantry, concrete barriers, repair and artillery. Slower but tougher.":"Kuch zirhidagi ogʻir piyodalar, beton toʻsiqlar, taʼmirlash va artilleriya. Sekinroq, lekin mustahkamroq.",
"Infantry HP":"Piyoda: mustahkamlik",
"Infantry speed":"Piyoda: tezlik",
"Jetpacks":"Jetpaklar",
"Tank":"Tank",
"Weapon damage: ":"Qurol zarari: ",
