"The \"Assembly hall\" is unlocked: it builds the super-heavy tank \"Bastion\" — one per army. Its weak spot is the rear.":"«Сехи васл» кушода шуд: дар он танки фавқулвазнини «Бастион» сохта мешавад — як барои ҳар лашкар. Ҷои заифаш — қафо.",
"The \"Incubator\" is unlocked: it grows the \"Reaper\" walker — one per army. Its weak spot is the glowing core underneath.":"«Инкубатор» кушода шуд: дар он роҳгарди «Даравгар» мерӯяд — як барои ҳар лашкар. Ҷои заифаш — ядрои дурахшони зери шикам.",
"Versus the \"Bastion\": hit it from the rear (nearly double damage), use air strikes, or tunnel behind it.":"Зидди «Бастион»: аз қафо занед (зарар қариб ду баробар), зарбаи ҳавоӣ диҳед ё ба қафояш нақб кобед.",
"Versus the \"Reaper\": shoot the glowing core from below (nearly double damage) and use air strikes.":"Зидди «Даравгар»: ба ядрои дурахшон аз поён тир занед (зарар қариб ду баробар) ва зарбаи ҳавоӣ диҳед.",
"ours":"аз мо",
"enemy":"душман",
"key":"тугма",
"rotate":"гардондан",
"Strip: ⟳ to rotate, or drag from the target along the run":"Рах: ⟳ — гардондан, ё аз ҳадаф ба самти ҳамла кашед",
"Strip: mouse wheel or R to rotate, or drag from the target along the run":"Рах: чархаки муш ё R — гардондан, ё аз ҳадаф ба самти ҳамла кашед",
"Into the tunnel: {0} vehicle(s)":"Ба нақб: {0} техника",
"Light and medium vehicles go into the nearest open tunnel":"Техникаи сабук ва миёна ба наздиктарин нақби кушода медарояд",
"Swarm. Squads within 70 m of the burrow (and selected ones), plus selected light/medium vehicles (Jackal, Hammer, Grad), go through the tunnel. Or: select and RMB/tap the burrow.":"Ғала. Дастаҳои то 70 м аз лона (ва интихобшудаҳо), инчунин техникаи сабук/миёнаи интихобшуда (Шағол, Путк, Град) аз нақб мегузаранд. Ё: интихоб карда, клики рост/ламс бар лона.",
"Air strikes":"Зарбаҳои ҳавоӣ",
"Carpet bombing and napalm: aiming, rotating the strip, enemy warning, calling from battle":"Бомбаборони густурда ва напалм: нишонгирӣ, гардондани рах, огоҳии душман, даъват аз набард",
"Terrain and lakes":"Релеф ва кӯлҳо",
"Lava burns, ice slides, methane explodes from fire, the rock hangar is cover":"Лава месӯзонад, ях мелағжонад, метан аз оташ метарканад, ангари кӯҳӣ — паноҳгоҳ",
"Swarm: tunnels":"Ғала: нақбҳо",
"You play the Swarm: tunnel burrow, exit up to 220 m, dust warning, squads and vehicles through":"Барои Ғала бозӣ мекунед: лонаи нақб, баромад то 220 м, огоҳии чанг, даста ва техника аз нақб",
"Consortium: fortifications":"Консорсиум: истеҳкомҳо",
"You play the Consortium: barrier chains, repair post, field repair by builders":"Барои Консорсиум бозӣ мекунед: занҷири монеаҳо, пости таъмир, таъмири саҳроии муҳандисон",
"Bosses":"Боссҳо",
"\"Bastion\" and \"Reaper\": from 12:00 (skipped here), plant, assembly, orders, weak spots, possession":"«Бастион» ва «Даравгар»: аз 12:00 (дар дарс гузаронида мешавад), сех, васл, фармонҳо, ҷойҳои заиф, идора",
"TARGET":"ҲАДАФ",
