"Veterancy carries over between battles. A squad earns XP (infantry 1, building 2, vehicle 3), levels, stars and perks. Veterans deploy first in a new battle. A lost squad loses everything and joins the Fallen.":"Собиқадорӣ байни набардҳо нигоҳ дошта мешавад. Даста таҷриба ҷамъ мекунад (пиёда 1, бино 2, техника 3), дараҷа, ситора ва перкҳо мегирад. Дар набарди нав собиқадорон аввал ба саф медароянд. Дастаи ҳалокшуда ҳамаашро гум карда, ба «Шаҳидон» меравад.",
