"{0} cycles: Strategist → Commander → Shooter · Alt+1/2/3 — straight to a mode":"{0} — давра: Стратег → Фармондеҳ → Тирандоз · Alt+1/2/3 — рост ба реҷа",
"Mode: {0}. Click or {1} — next; hold or RMB — pick; Alt+1/2/3 — direct":"Реҷа: {0}. Клик ё {1} — навбатӣ; нигоҳ доштан ё клики рост — интихоб; Alt+1/2/3 — рост",
