"possess the selection (nothing selected — to battle)":"идораи интихобшуда (ҳеҷ чиз интихоб нашуда — ба набард)",
"mode cycle: Strategist → Commander → Shooter · Alt+1/2/3 — direct":"давраи реҷа: Стратег → Фармондеҳ → Тирандоз · Alt+1/2/3 — рост",
"strategy (the same key there possesses the selection)":"стратегия (он ҷо ҳамон тугма — идораи интихобшуда)",
"strategy (cycle: Strategist → Commander → Shooter; P / Alt+2 — straight to Commander)":"стратегия (давра: Стратег → Фармондеҳ → Тирандоз; P / Alt+2 — рост ба Фармондеҳ)",
"\"Commander\" on phone (off — hide)":"«Фармондеҳ» дар телефон (хомӯш — пинҳон)",
"One button, three modes: Strategist → Commander → Shooter. Top view of one squad, click orders, 4 abilities, squad switching, diving into the shooter and back":"Як тугма — се реҷа: Стратег → Фармондеҳ → Тирандоз. Намуди боло ба як даста, фармон бо клик, 4 қобилият, иваз кардани даста, ғӯта ба тирандоз ва бозгашт",
"One button, three modes in a cycle: Strategist → Commander → Shooter. Press {0} or the mode button below (next to \"▶ Possess\") to get to Commander. Straight there — P or Alt+2.":"Як тугма — се реҷа бо давра: Стратег → Фармондеҳ → Тирандоз. Барои ба Фармондеҳ рафтан {0} ё тугмаи реҷаро дар поён пахш кунед (паҳлӯи «▶ Идора»). Рост — P ё Alt+2.",
"Switch squads: {0} — the next one (closest to the fight first), a card on the left or the middle mouse button on a squad. The previous squad keeps its order.":"Дастаро иваз кунед: {0} — навбатӣ (аввал наздиктарин ба набард), корти чап ё тугмаи миёнаи муш бар даста. Дастаи пешина фармонашро идома медиҳад.",
"Next on the ladder is the Shooter: {0} or the mode button. Also: double LMB on a trooper or F. Wheel all the way in — third person.":"Дар зинапоя навбатӣ — Тирандоз: {0} ё тугмаи реҷа. Инчунин: ду бор клики чап бар ҷанговар ё F. Чархакро то охир ба дарун — шахси сеюм.",
"{0} in the shooter cycles on to the Strategist. Straight to Commander — P or Alt+2 (or hold the mode button and pick ⌖). Squad veterancy is kept: menu → \"My squads\".":"{0} дар тирандоз бо давра ба Стратег мебарад. Рост ба Фармондеҳ — P ё Alt+2 (ё тугмаи реҷаро нигоҳ дошта ⌖-ро интихоб кунед). Собиқадорӣ нигоҳ дошта мешавад: меню → «Дастаҳои ман».",
"The mode button at the top right: tap — next mode in the cycle (Strategist → Commander → Shooter). Tap it to get to Commander ⌖. Hold — pick one of three.":"Тугмаи реҷа дар болои рост: ламс — реҷаи навбатӣ бо давра (Стратег → Фармондеҳ → Тирандоз). Ламс кунед — ба Фармондеҳ ⌖ меравед. Нигоҳ доштан — интихоб аз се.",
"Tap another card on the left or ⇆ at the top — the next squad (closest to the fight first).":"Корти дигари чап ё ⇆-и болоро ламс кунед — дастаи навбатӣ (аввал наздиктарин ба набард).",
"Tap the mode button \"▶ Fight\" — next on the ladder, the Shooter. Or double-tap a trooper of the squad.":"Тугмаи реҷаи «▶ Ба набард»-ро ламс кунед — дар зинапоя навбатӣ, Тирандоз. Ё ду бор бар ҷанговари даста ламс кунед.",
"Hold the mode button — three icons appear — pick ⌖ Commander. (A plain tap cycles on to the Strategist.) Veterancy is kept: menu → \"My squads\".":"Тугмаи реҷаро нигоҳ доред — се нишона пайдо мешавад — ⌖ Фармондеҳро интихоб кунед. (Ламси оддӣ бо давра ба Стратег мебарад.) Собиқадорӣ нигоҳ дошта мешавад: меню → «Дастаҳои ман».",
