"Living world: requests, hero quests, breakthrough ops":"Ҷаҳони зинда: дархостҳо, супоришҳои қаҳрамонон, амалиётҳои гардиш",
"Living world":"Ҷаҳони зинда",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Худиҳо ёрӣ мепурсанд ва мукофот медиҳанд, қаҳрамонон супориш медиҳанд, фронти истодаро бо амалиёт мешикананд",
"A request":"Дархости худиҳо",
"Breakthrough":"Гардиш",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Худиҳо баъзан ёрӣ мепурсанд: овоз тавассути радио, корти «ДАРХОСТ» ва нишонаи ✋. Дастаро фишор додаанд — душманони наздаш нобуд кунед. Мукофот: ҷанговар бо капсула аз пойгоҳ, силоҳ аз кузови багги, ҷойи тирандоз ё пушонидан аз мадор. Намехоҳед — ✕ ё нодида гиред.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Кашшофи собиқадор «Чуғз» супориш пешниҳод мекунад. Y — қабул (N — рад). Ба нишонаи ★ равед, посбононро нобуд кунед ва 3 с назди халабон истед — ӯ ба дастаи шумо ҳамроҳ мешавад.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Фронт истод — ситод гардишро пешниҳод мекунад. Y — қабул. Ретрансляторро 8 с бе душмани наздик нигоҳ доред: харитаи душман 60 с намоён. Генератор — турелҳои душман 2 дақ хомӯш. Дар Стратег — «Ба даста супоридан». Душман ҳам ин корро карда метавонад: ба ⚠ нигаред.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Худиҳо ёрӣ мепурсанд: корти «ДАРХОСТ» ва нишонаи ✋. Душманони назди дастаи фишордидаро нобуд кунед — мукофот гиред. ✕ — гузаштан.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"Қаҳрамон «Чуғз» супориш пешниҳод мекунад — «Қабул»-ро ламс кунед. Ба ★ равед, посбононро нобуд кунед, назди халабон истед.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Фронт истод — «Қабул»-ро ламс кунед ва ретрансляторро 8 с нигоҳ доред: харитаи душман як дақиқа кушода мешавад.",
