"LANDING":"ФУРУД",
"REDEPLOY":"ИНТИҚОЛ",
"Steel fluff stuck to you — corrodes armour −2/s. Stand still 3 s out of combat or find an engineer":"Пахмоки пӯлодин часпид — зиреҳро мехӯрад −2/с. Берун аз набард 3 с истед ё назди муҳандис равед",
"An engineer brushed the fluff off":"Муҳандис пахмокро тоза кард",
