"Heart of the base: squads, engineers, pods, research. Lose it and you lose.":"Дили пойгоҳ: дастаҳо, муҳандисон, капсулаҳо, таҳқиқот. Онро аз даст диҳед — шикаст.",
"Produces: ":"Истеҳсол мекунад: ",
"Launch pad":"Майдончаи партоб",
"A silo next to the HQ: pods, supply crates and bombers launch from here through the sky portal. Nothing can be built on it.":"Шахта дар назди ситод: капсулаҳо, қуттиҳои таъминот ва бомбаандозҳо аз ин ҷо тавассути портали осмон парвоз мекунанд. Дар он сохтан мумкин нест.",
"Economy":"Иқтисод",
"Key building":"Бинои калидӣ",
"Building":"Бино",
"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"Ҷои заиф — қафо (муҳаррик): зарар ×{0}. Тӯп, 2 манораи пулемёт, кассетаи мушак; хеле суст мегардад — аз паҳлу давр занед.",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"Ҷои заиф — ядрои дурахшон дар зери шикам: аз поён зарар ×{0}. Нури таҳриф ва пойкӯбии майдонӣ; аз монеаҳо мегузарад — масофа нигоҳ доред, ҷамъ нашавед.",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"Зидди он: бомбаҳо ва артиллерия (×{0}), мушакҳо (×{1}), бомбаборони густурда; тирҳо қариб беасаранд (×{2}).",
"Faction":"Фраксия",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"Мошинҳои тез, галаҳои дрон, нақбҳо ва барқароршавӣ. Пиёдагон сабуктар, вале тезтар; тӯпҳо ва релсотронҳо сахттар мезананд.",
"Heavy power-armoured infantry, concrete barriers, repair and artillery. Slower but tougher.":"Пиёдагони вазнин дар зиреҳи қувваӣ, монеаҳои бетонӣ, таъмир ва артиллерия. Сусттар, вале устувортар.",
