"2. Play and think aloud: what is unclear, annoying, fun. The corner shows version, time and FPS — they match the recording to the notes.":"2. Бозӣ кунед ва баланд фикр кунед: чӣ норавшан, чӣ асабонӣ мекунад, чӣ ҷолиб аст. Дар кунҷ версия, вақт ва FPS намоёнанд — бо онҳо сабт бо қайдҳо мувофиқ карда мешавад.",
