"Veterancy carries over between battles. A squad earns XP (infantry 1, building 2, vehicle 3), levels, stars and perks. Veterans deploy first in a new battle. A lost squad loses everything and joins the Fallen.":"老兵等级跨战斗保留。小队获得经验（步兵 1、建筑 2、载具 3），升级并获得星级与天赋。新战斗中老兵优先出战。阵亡的小队失去一切，列入“阵亡”。",
