"\"Commander\" mode on phone":"手机上的“指挥官”模式",
"Smoke grenades":"烟雾弹",
"A screen at a point for 14 s — enemies cannot see through.":"在一点布下烟幕 14 秒——敌人无法看穿。",
"Flank sprint":"侧翼冲刺",
"Run to a point at ×1.6 speed without stopping to fight (7 s).":"以 ×1.6 速度冲向一点，途中不停下交战（7 秒）。",
"Suppressing fire":"压制射击",
"Saturating fire on a 14 m area: enemies slowed and missing (7 s).":"对 14 米区域饱和射击：敌人减速且失准（7 秒）。",
"Field medic":"战地医疗",
"+20% hull to all at once, then 4 s of repair.":"立即为全员恢复 20% 耐久，之后再修复 4 秒。",
"Regen burst":"再生爆发",
"Swarm: 8 s of fast regeneration for the whole squad.":"虫群：全队快速再生 8 秒。",
"Grenade volley":"手雷齐投",
"Every trooper throws a grenade at the point.":"每名士兵向目标点投一枚手雷。",
"AT rocket":"反坦克火箭",
"Heavy rockets at a vehicle or building (up to 3).":"向载具或建筑发射重型火箭（最多 3 枚）。",
"Jet leap":"喷气跃进",
"The squad jet-leaps to a point (up to 80 m).":"小队用喷气背包跃进到目标点（最远 80 米）。",
"Mini barrier":"迷你路障",
"Consortium: a concrete section in front of the squad for 40 s.":"财团：在小队前方立起一段混凝土墙，持续 40 秒。",
"No squads to command — order a squad":"没有可指挥的小队——先下单一支",
"Commander: {0}. LMB — move / attack, 1–4 — abilities, Tab — next squad, double-click a trooper — fight, P — strategy":"指挥官：{0}。左键——移动/攻击，1–4——技能，Tab——下一支小队，双击士兵——参战，P——战略",
"Tap — move/attack, double-tap a trooper — fight, right buttons — abilities":"点按——移动/攻击，双击士兵——参战，右侧按钮——技能",
"Strategy":"战略",
"Commanding: {0}":"指挥中：{0}",
"cooling down":"冷却中",
"s":"秒",
"Pick a point on the ground":"请选择地面上的一点",
"No troops":"没有士兵",
"{0} lost. Commanding: {1} (closest to the fight)":"{0} 已覆灭。改为指挥：{1}（离战斗最近）",
"Commanding: {0} (closest to the fight)":"指挥中：{0}（离战斗最近）",
"No squads left — strategy":"没有小队了——回到战略",
" tr.":" 人",
"No abilities":"无技能",
"COMMANDER":"指挥官",
"Fight: possess a trooper of the squad":"参战：附身小队中的一名士兵",
"Fight":"参战",
"Tap a point on the map (or the same button to cancel)":"点按地图上的一点（再按同一按钮取消）",
"LMB — where to use · same key — at cursor · RMB / Esc — cancel":"左键——施放位置 · 再按同键——施放于光标处 · 右键 / Esc——取消",
"Tap — move / attack · double-tap a trooper — fight · drag — rotate, pinch — zoom":"点按——移动/攻击 · 双击士兵——参战 · 拖动——旋转，双指——缩放",
"LMB — move / attack (2× run) · double-click a trooper — fight · Tab — squad · Q/E, wheel — camera · H — hold":"左键——移动/攻击（双击——奔跑）· 双击士兵——参战 · Tab——小队 · Q/E、滚轮——镜头 · H——原地坚守",
"Commander":"指挥官",
"Commander mode: top view of one squad, abilities 1–4":"指挥官模式：俯瞰单支小队，技能 1–4",
"Top view of your squad: click orders, abilities 1–4.":"俯瞰你的小队：点击下令，技能 1–4。",
"Hold position":"坚守阵地",
"The third mode: top view of one squad, click orders, 4 abilities, squad switching, diving into the shooter and back":"第三种模式：俯瞰单支小队、点击下令、4 种技能、切换小队、切入射手并返回",
"SQUAD":"小队",
"Commander mode":"指挥官模式",
"Move in formation":"编队移动",
"Squad ability":"小队技能",
"Another squad":"另一支小队",
"Dive into the shooter":"切入射手",
"Back to Commander":"返回指挥官",
"Turn on the third mode, Commander: the P key or the \"⌖ Commander\" button at the bottom next to \"▶ Possess\". The camera drops to the squad — 27 m above it, at an angle.":"开启第三种模式——指挥官：按 P 键，或点底部“▶ 附身”旁的“⌖ 指挥官”按钮。镜头会降到小队上方 27 米处，呈斜角。",
"LMB on the \"HERE\" marker — the squad moves there in formation. LMB on an enemy — attack, double LMB on the ground — run. Q/E and the wheel — camera.":"左键点击“到这里”标记——小队编队前往。左键点击敌人——攻击，双击地面——奔跑。Q/E 和滚轮——镜头。",
"Four squad abilities — keys 1–4 or the buttons below. Smoke, sprint and suppression — then LMB on a point (the same key again — at the cursor). Medic — instantly.":"四种小队技能——按 1–4 或底部按钮。烟雾、冲刺和压制——之后左键点击目标点（再按同键——施放于光标处）。医疗——立即生效。",
"Switch squads: Tab, a card on the left or the middle mouse button on a squad. The previous squad carries on with its last order.":"切换小队：Tab、左侧卡片，或用鼠标中键点击小队。前一支小队会继续执行最后的命令。",
"Double LMB on a trooper of your squad (or F, \"▶ Fight\") — dive into the shooter. Wheel all the way in — into the trooper in third person.":"双击你小队中的一名士兵（或按 F、“▶ 参战”）——切入射手。滚轮一直向内滚——以第三人称进入士兵视角。",
"{0} in the shooter — back to Commander over the same squad; P — to the Strategist. Squad veterancy carries over between battles: menu → \"My squads\".":"射手模式下按 {0}——回到同一小队的指挥官视角；P——回到战略家。小队老兵等级跨战斗保留：菜单 →“我的小队”。",
"Tap ⌖ at the top right — Commander mode. On a phone turn it on in Settings (\"Commander mode on phone\"); in the lesson it is already on.":"点按右上角的 ⌖——指挥官模式。手机上需在设置中开启（“手机上的指挥官模式”）；教程中已开启。",
"Tap the \"HERE\" marker — the squad moves in formation. Tap an enemy — attack. Drag — rotate the camera, pinch — zoom.":"点按“到这里”标记——小队编队前往。点按敌人——攻击。拖动——旋转镜头，双指——缩放。",
"The round buttons at the bottom right are 4 abilities. Smoke, sprint, suppression — then tap a point on the map.":"右下角的圆形按钮是 4 种技能。烟雾、冲刺、压制——之后点按地图上的目标点。",
"Tap another card on the left — the camera flies to that squad.":"点按左侧另一张卡片——镜头会飞到那支小队。",
"Double-tap a trooper of the squad or \"▶ Fight\" — dive into the shooter.":"双击小队中的一名士兵或点“▶ 参战”——切入射手。",
"\"◩ Strategy\" in the shooter brings you back to Commander over the same squad. Squad veterancy carries over: menu → \"My squads\".":"射手模式下点“◩ 战略”会回到同一小队的指挥官视角。老兵等级会保留：菜单 →“我的小队”。",
"❄ Frozen by coolant: −60% speed, explosions hurt more (8 s)":"❄ 被冷却液冻结：速度 −60%，爆炸伤害加重（8 秒）",
"⤒ Dislocation! The sky portal is pulling you up…":"⤒ 错位！天空传送门正把你吸上去…",
"⤓ Exit at the antipode — disoriented for 2 s":"⤓ 从对跖点出来——晕头转向 2 秒",
"anomaly discharged":"异常已释放",
"discharged, dormant for":"已释放，休眠",
