"DISLOCATION EXIT":"错位出口",
"m":"米",
"📻 MUFFLER — no radio, no support":"📻 静默区——无通讯、无支援",
"Dislocation":"错位",
"Mosaic":"马赛克",
"Coolant geyser":"冷却液间歇泉",
"Draught":"穿堂风",
"Muffler":"静默区",
"Anomaly! Dust falling upwards — a Dislocation, it will pull you into the sky!":"异常！尘土往上落——是错位，会把你吸上天！",
"Dislocation ahead — step in and you come out on the other side of the meteor!":"前方有错位——踏进去会从陨石的另一侧出来！",
"Anomaly — the picture breaks into pixels! A Mosaic, aim goes wild!":"异常——画面碎成像素！是马赛克，准星乱飘！",
"Pixel square — go around, everything jerks in there.":"像素方块——绕开走，里面一切都在抽搐。",
"Frost on the ground — a coolant geyser! It will freeze you!":"地上结霜——是冷却液间歇泉！会把你冻住！",
"Hear the hiss? Geyser, back off!":"听到嘶嘶声了吗？是间歇泉，后退！",
"A strip of haze — a Draught, it blows even rockets away!":"一道热浪——是穿堂风，连火箭都能吹偏！",
"Draught ahead, hold on!":"前方穿堂风，抓稳了！",
"Grey static — a Muffler! We lose the radio in there!":"灰色雪花噪点——是静默区！进去就断联！",
"Muffler ahead: no radio, no support.":"前方静默区：没有无线电，没有支援。",
"Muffler: no signal":"静默区：无信号",
"Wasteland":"荒原",
"Green anomalous zone":"绿色异常区",
"Russet belt":"赤褐带",
"White cap":"白冠",
"grass hides infantry: unseen beyond 40 m unless firing":"草丛隐藏步兵：不开火时 40 米外看不见",
"leaves rustle: runners are heard 32 m away":"落叶沙沙响：奔跑声 32 米外可闻",
"snow: infantry −15% speed, sight ×0.7":"雪地：步兵速度 −15%，视野 ×0.7",
"Whiproot":"鞭根",
