"Verdan":"绿灵",
"destroyed, a spray of green sap":"被摧毁，溅出绿色汁液",
"ANGRY":"暴怒",
"A Verdan! This plant bites!":"绿灵！这植物会咬人！",
"Don't touch the plants — they get angry!":"别碰这些植物——它们会发怒！",
"Biomes and anomalies":"生物群系与异常",
"Green grass hides infantry, sharp biome borders, the Dislocation throws you to the antipode, Verdans are neutral until provoked":"绿草隐藏步兵、群系边界分明、错位会把你甩到对跖点、绿灵不受惊扰时保持中立",
"GRASS":"草地",
"ACROSS":"越过边界",
"DISLOCATION":"错位",
"VERDAN":"绿灵",
"Green zone":"绿色区域",
"Sharp border":"分明的边界",
"The meteor now has biomes: green grass, russet autumn, snow — with sharp borders. Walk to the \"GRASS\" marker. In the green zone grass hides infantry: enemies beyond 40 m cannot see you unless you fire.":"陨石如今有了生物群系：绿草、赤褐秋林、雪原——边界分明。走到“草地”标记处。绿色区域里草丛会隐藏步兵：只要你不开火，40 米外的敌人就看不见你。",
"Cross the border to the marker. In the Russet belt footsteps are louder (runners are heard 32 m away), in the White cap infantry is 15% slower and sight is ×0.7.":"越过边界走到标记处。赤褐带里脚步声更响（奔跑声 32 米外可闻），白冠里步兵慢 15%，视野 ×0.7。",
"Second-wave anomalies. The Dislocation — dust falls upwards. Step in: the sky portal takes you and ~5 s later you exit at the antipode (both teams see the exit). Also: Mosaic (pixels, spread), Geyser (freeze), Draught (pushes), Muffler (no radio). A bolt (E) or a grenade discharges an anomaly.":"第二波异常。错位——尘土往上落。走进去：天空传送门会把你带走，约 5 秒后从对跖点出来（双方都能看到出口）。另有：马赛克（像素化、散布）、间歇泉（冻结）、穿堂风（推开）、静默区（断联）。螺栓（E）或手雷可释放异常。",
"A Verdan is a living alien plant. It is neutral until you touch it or come close, but dangerous to both factions. This one is a Sporecap: destroy it from range (LMB) without walking into the spore cloud. Fire burns Verdans harder.":"绿灵是一种活的外星植物。你不碰它、不靠近，它就保持中立，但对双方阵营都很危险。这株是孢子菇：从远处消灭它（左键），别走进孢子云。火焰对绿灵伤害更高。",
"The meteor now has biomes with sharp borders. Use the stick to walk to the \"GRASS\" marker. Grass hides infantry beyond 40 m unless you fire.":"陨石如今有了边界分明的生物群系。用摇杆走到“草地”标记。只要不开火，草丛会在 40 米外隐藏步兵。",
"Cross the border to the marker. Autumn — louder steps, snow — slower and worse sight.":"越过边界走到标记处。秋林——脚步更响；雪地——更慢、视野更差。",
"The Dislocation — dust falls upwards. Step in: it lifts you to the sky and ~5 s later drops you at the antipode. The ⏏ button near an anomaly throws a bolt to discharge it.":"错位——尘土往上落。走进去：它会把你抬上天，约 5 秒后丢到对跖点。异常旁的 ⏏ 按钮可扔出螺栓将其释放。",
"A Verdan is neutral until you come close. Destroy the Sporecap from range — shoot.":"你不靠近，绿灵就保持中立。从远处消灭孢子菇——开火。",
