"Mode button at the top right: tap — next (Strategist → Commander → Shooter), hold — pick":"右上角的模式按钮：点按——下一个（战略家 → 指挥官 → 射手），长按——选择",
"{0} cycles: Strategist → Commander → Shooter · Alt+1/2/3 — straight to a mode":"{0} 循环切换：战略家 → 指挥官 → 射手 · Alt+1/2/3——直接进入某模式",
"Mode: {0}. Click or {1} — next; hold or RMB — pick; Alt+1/2/3 — direct":"模式：{0}。点击或 {1}——下一个；长按或右键——选择；Alt+1/2/3——直达",
