"mode cycle: Strategist → Commander → Shooter · Alt+1/2/3 — direct":"模式循环：战略家 → 指挥官 → 射手 · Alt+1/2/3——直达",
"strategy (the same key there possesses the selection)":"战略（在战略中按同一键可附身选中单位）",
"strategy (cycle: Strategist → Commander → Shooter; P / Alt+2 — straight to Commander)":"战略（循环：战略家 → 指挥官 → 射手；P / Alt+2——直达指挥官）",
"\"Commander\" on phone (off — hide)":"手机上的“指挥官”（关闭则隐藏）",
"One button, three modes: Strategist → Commander → Shooter. Top view of one squad, click orders, 4 abilities, squad switching, diving into the shooter and back":"一个按钮，三种模式：战略家 → 指挥官 → 射手。俯瞰单支小队、点击下令、4 种技能、切换小队、切入射手并返回",
"One button, three modes in a cycle: Strategist → Commander → Shooter. Press {0} or the mode button below (next to \"▶ Possess\") to get to Commander. Straight there — P or Alt+2.":"一个按钮，三种模式循环：战略家 → 指挥官 → 射手。按 {0} 或底部的模式按钮（“▶ 附身”旁）进入指挥官。直达——P 或 Alt+2。",
"Switch squads: {0} — the next one (closest to the fight first), a card on the left or the middle mouse button on a squad. The previous squad keeps its order.":"切换小队：{0}——下一支（优先离战斗最近的），左侧卡片，或鼠标中键点击小队。前一支小队保持原命令。",
"Next on the ladder is the Shooter: {0} or the mode button. Also: double LMB on a trooper or F. Wheel all the way in — third person.":"阶梯上的下一个是射手：{0} 或模式按钮。也可以：双击士兵或按 F。滚轮一直向内——第三人称。",
"{0} in the shooter cycles on to the Strategist. Straight to Commander — P or Alt+2 (or hold the mode button and pick ⌖). Squad veterancy is kept: menu → \"My squads\".":"射手模式下按 {0} 会循环到战略家。直达指挥官——P 或 Alt+2（或长按模式按钮选 ⌖）。老兵等级会保留：菜单 →“我的小队”。",
"The mode button at the top right: tap — next mode in the cycle (Strategist → Commander → Shooter). Tap it to get to Commander ⌖. Hold — pick one of three.":"右上角的模式按钮：点按——循环到下一模式（战略家 → 指挥官 → 射手）。点按即可进入指挥官 ⌖。长按——三选一。",
"Tap another card on the left or ⇆ at the top — the next squad (closest to the fight first).":"点按左侧另一张卡片或顶部的 ⇆——下一支小队（优先离战斗最近的）。",
"Tap the mode button \"▶ Fight\" — next on the ladder, the Shooter. Or double-tap a trooper of the squad.":"点按模式按钮“▶ 参战”——阶梯上的下一个：射手。或双击小队中的一名士兵。",
"Hold the mode button — three icons appear — pick ⌖ Commander. (A plain tap cycles on to the Strategist.) Veterancy is kept: menu → \"My squads\".":"长按模式按钮——出现三个图标——选择 ⌖ 指挥官。（普通点按会循环到战略家。）老兵等级会保留：菜单 →“我的小队”。",
