"Breakthrough":"破局",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"友军有时会求援：无线电呼叫、“求援”卡片和 ✋ 标记。一支小队被压制——消灭它附近的敌人。奖励：从基地空投一名士兵、越野车斗里的枪、射手座位或轨道掩护。不想管——点 ✕ 或直接无视。",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"老兵侦察员“夜枭”发布任务。Y——接受（N——拒绝）。前往 ★ 标记，清掉守卫，在飞行员身边停留 3 秒——他会加入你的小队。",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"战线僵持——总部提出破局行动。Y——接受。在附近无敌人时守住中继站 8 秒：敌方地图显示 60 秒。发电机——敌方炮塔沉默 2 分钟。战略家模式下——“指派小队”。敌人也会这么干：留意 ⚠。",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"友军求援：“求援”卡片和 ✋ 标记。消灭被压制小队附近的敌人——领取奖励。✕——跳过。",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"英雄“夜枭”发布任务——点按“接受”。前往 ★，清掉守卫，待在飞行员身边。",
