"You hear crackling; dash through between discharges.":"能听到噼啪声；在两次放电之间冲过去。",
"Step on it and a pillar of fire bursts out. The air shimmers above it.":"踩上去就会喷出火柱。上方空气在扭曲。",
"Watch for heat haze underfoot; a bolt sets it off early.":"留意脚下的热浪扭曲；扔螺栓可以提前引爆它。",
"A drifting green cloud: damage over time while inside.":"漂移的绿色云团：身处其中会持续受到伤害。",
"It drifts slowly — just step out of its way.":"它漂得很慢 — 让开它的路线即可。",
"A drifting space distortion: bends bullets and warps the screen.":"漂移的空间扭曲：使子弹偏转，画面晃动。",
"Don't shoot through it — bullets veer off.":"别隔着它射击 — 子弹会偏。",
"Dust falls upwards: a unit is pulled into the sky portal and thrown out at the antipode ~5 s later (exit visible to both sides).":"尘土“向上坠落”：单位被吸入天空传送门，约 5 秒后从对跖点抛出（双方都能看到出口）。",
"Can be used as a teleport — but enemies see the exit.":"可当传送门用 — 但敌人能看到出口。",
"A 10×10 m square of big \"pixels\": jerky movement, +50% spread, AI loses targets.":"10×10 米的大“像素”方块：移动一卡一卡，散布 +50%，AI 丢失目标。",
"Cover from the AI, but hard to shoot from.":"能躲避 AI，但从里面很难射击。",
"Frost on the ground, 2 s of hissing — then a steam column: freeze (−60% speed, +40% blast damage, 8 s). Snow.":"地面结霜，嘶嘶响 2 秒 — 然后喷出蒸汽柱：冻结（速度 −60%，爆炸伤害 +40%，8 秒）。雪地。",
"Hear the hiss — step aside at once.":"听到嘶嘶声就立刻闪开。",
"A 6×30 m strip of haze pushes units, jetpacks and even projectiles; direction changes every 2 minutes. Autumn.":"6×30 米的热浪带会推动单位、喷气背包甚至弹丸；方向每 2 分钟变化。秋季。",
"Rockets drift through it — lead your shots.":"火箭穿过时会被吹偏 — 记得提前量。",
"Grey static: no radio or support inside, robot vision ×0.4, shots are quiet.":"灰色噪点：区域内没有无线电和支援，机器人视野 ×0.4，枪声很小。",
"Good for ambushes, bad for calling support.":"适合伏击，不适合呼叫支援。",
"A meadow of steel dandelions: fluff sticks and corrodes armour −2/s, jumps to neighbours on contact.":"一片钢铁蒲公英：绒毛粘上后每秒腐蚀护甲 −2，接触时会传染给旁人。",
"Clean: an engineer nearby (1.5 s) or stand still 3 s out of combat; an explosion or bolt blows it away.":"清除：附近有工程师（1.5 秒），或在非战斗中原地不动 3 秒；爆炸或螺栓能吹散绒毛。",
"A rootstock with vines: barely moves, lashes everyone nearby (damage and knockback).":"带藤蔓的根茎：几乎不移动，用藤鞭抽打附近所有目标（伤害并击退）。",
"Hit it from range — beyond its aggro radius it is harmless.":"远程攻击它 — 在激怒范围外它是无害的。",
"A mushroom with a glowing cap: touch or approach it and it bursts into spores (damage and suppression, 6 s).":"顶着发光菌盖的蘑菇：触碰或靠近就会喷出孢子云（伤害并压制，6 秒）。",
"Shoot from afar or walk around.":"远程射击或绕开。",
"Armoured and slow, bullets barely work; anger it and it rams.":"装甲厚、动作慢，子弹几乎无效；激怒它就会冲撞。",
"Rockets, grenades, fire.":"火箭、手雷、火焰。",
"A three-legged hunter: get close and it chases you and claws, gives up after 20 s.":"三足猎手：靠近就会追上来用爪攻击，20 秒后放弃。",
"Keep your distance or escape by jetpack.":"保持距离，或用喷气背包逃离。",
"A rootstock on root legs: burrows (a dust mound moves underground, invulnerable), surfaces under its target and tosses it.":"靠根足行走的根茎：钻入地下（土包在地下移动，无敌），从目标脚下钻出并把它掀飞。",
"Watch the mound and back off; hit it while it is above ground.":"盯住土包并后撤；趁它在地面上时攻击。",
"A cloud of glowing worms: chases you and nibbles; bullets barely work.":"一团发光的虫子：追着你一点点“啃咬”；子弹几乎无效。",
"An explosion scatters it for 6 s — a grenade beats the MG.":"爆炸能把虫群驱散 6 秒 — 手雷比机枪好用。",
"Dust and basalt, caps around the HQs, lava. Standard combat rules.":"尘土与玄武岩，总部周围的高台，熔岩。常规战斗规则。",
"Emerald grass, spores, crystals: the grass hides infantry beyond 40 m until it fires. Verdans live here.":"翡翠色的草、孢子、晶体：草丛会在 40 米外隐藏步兵，直到他们开火。绿灵生活在这里。",
"Autumn leaves: footsteps are louder — the enemy hears runners at 32 m. Draughts and Steel fluff appear here.":"秋叶：脚步声更响 — 敌人能在 32 米外听到奔跑者。穿堂风和钢绒出现在这里。",
"Snow: infantry −15% speed, vision ×0.7, an ice lake nearby; blizzards and coolant geysers.":"雪地：步兵速度 −15%，视野 ×0.7，附近有冰湖；暴风雪和冷却液间歇泉。",
"Visibility ×0.65, footsteps are silent.":"能见度 ×0.65，听不到脚步声。",
"Visibility 25 m: the AI cannot target beyond it.":"能见度 25 米：AI 无法锁定更远的目标。",
"From big explosions, wrecks and napalm (30 s): targets in smoke beyond 10 m are hidden.":"来自大爆炸、残骸和燃烧弹（30 秒）：烟雾中 10 米外的目标不可见。",
"White cap only: visibility ×0.5, a white veil.":"仅限白冠：能见度 ×0.5，一片白茫茫。",
"Dust storm and meteor shower":"沙尘暴和陨石雨",
"Cut vision hard; falling rocks hit everyone — take cover.":"严重削弱视野；天上落下的石块会砸中所有人 — 快找掩护。",
"Three modes — one button":"三种模式 — 一个按钮",
"Ladder":"阶梯",
"Strategist → Commander → Shooter: one mode button (PC Tab/P, phone — top button, gamepad — View; hold to pick).":"战略家 → 指挥官 → 射手：一个模式按钮（PC 用 Tab/P，手机用顶部按钮，手柄用 View；按住可选择）。",
"Pause: Esc / ☰ / Menu. Help: F1 in battle, full key list \"/\". Clean screen F9.":"暂停：Esc / ☰ / Menu。帮助：战斗中按 F1，完整按键列表 “/”。简洁界面 F9。",
"Mode":"模式",
"Top view: building, production, group orders, CP support. LMB select, RMB order; on phone — taps and the build panel.":"俯视视角：建造、生产、编组指令、用指挥点呼叫支援。左键选择，右键下令；手机上用点按和建造面板。",
"Buildings: Z X C V B N K · v8.0 groups on the right · ":"建筑：Z X C V B N K · 右侧为 v8.0 编组 · ",
"Tilted camera over your squad: click to move, on an enemy to attack, 1–4 abilities, Tab next squad, double-click a trooper to dive into the shooter.":"小队上方的倾斜镜头：点击移动，点击敌人攻击，1–4 技能，Tab 切换下一小队，双击士兵切入射手模式。",
"Camera: Q/E, wheel, WASD, Space — back to squad.":"镜头：Q/E、滚轮、WASD，Space 回到小队。",
"First-person combat as any trooper or vehicle. Jetpack, slide, grenade, rocket, reflex, artillery, rifle-butt melee.":"以任意士兵或载具进行第一人称战斗。喷气背包、滑铲、手雷、火箭、反射、炮击、枪托近战。",
"Phone: left joystick to move, right half to look, buttons on the right.":"手机：左摇杆移动，右半屏转视角，按钮在右侧。",
