"Automatic machine gun. Can be manned. Consortium: cheaper ({0}), toughness ×{1}, damage ×{2}.":"Ametralladora automática. Se puede poseer. Consorcio: más barata ({0}), blindaje ×{1}, daño ×{2}.",
