"Veterancy carries over between battles. A squad earns XP (infantry 1, building 2, vehicle 3), levels, stars and perks. Veterans deploy first in a new battle. A lost squad loses everything and joins the Fallen.":"La veteranía se conserva entre batallas. La escuadra gana XP (infantería 1, edificio 2, vehículo 3), niveles, estrellas y ventajas. Los veteranos salen primero en una nueva batalla. Una escuadra caída lo pierde todo y pasa a Caídos.",
