"\"Commander\" mode on phone":"Modo “Comandante” en el móvil",
"Smoke grenades":"Granadas de humo",
"A screen at a point for 14 s — enemies cannot see through.":"Una cortina en un punto durante 14 s: el enemigo no ve a través.",
"Flank sprint":"Carrera de flanqueo",
"Run to a point at ×1.6 speed without stopping to fight (7 s).":"Corre a un punto a ×1.6 de velocidad sin pararse a pelear (7 s).",
"Suppressing fire":"Fuego de supresión",
"Saturating fire on a 14 m area: enemies slowed and missing (7 s).":"Fuego de saturación en 14 m: enemigos ralentizados y fallando (7 s).",
"Field medic":"Médico de campo",
"+20% hull to all at once, then 4 s of repair.":"+20 % de blindaje a todos al instante, luego 4 s de reparación.",
"Regen burst":"Regeneración",
"Swarm: 8 s of fast regeneration for the whole squad.":"Enjambre: 8 s de regeneración rápida para toda la escuadra.",
"Grenade volley":"Lluvia de granadas",
"Every trooper throws a grenade at the point.":"Cada soldado lanza una granada al punto.",
"AT rocket":"Cohete AT",
"Heavy rockets at a vehicle or building (up to 3).":"Cohetes pesados contra un vehículo o edificio (hasta 3).",
"Jet leap":"Salto propulsado",
"The squad jet-leaps to a point (up to 80 m).":"La escuadra salta con propulsores hasta un punto (hasta 80 m).",
"Mini barrier":"Minibarrera",
"Consortium: a concrete section in front of the squad for 40 s.":"Consorcio: un tramo de hormigón ante la escuadra durante 40 s.",
"No squads to command — order a squad":"No hay escuadras que mandar: encarga una",
"Commander: {0}. LMB — move / attack, 1–4 — abilities, Tab — next squad, double-click a trooper — fight, P — strategy":"Comandante: {0}. Clic izq. — mover / atacar, 1–4 — habilidades, Tab — otra escuadra, doble clic en un soldado — al combate, P — estrategia",
"Tap — move/attack, double-tap a trooper — fight, right buttons — abilities":"Toque — mover/atacar, doble toque en un soldado — al combate, botones a la derecha — habilidades",
