"Launches a pod with a fresh squad from the base: through the sky portal to your forces.":"Lanza desde la base una cápsula con una escuadra nueva: por el portal celeste hasta tus fuerzas.",
"Faster pod launches":"Lanzamiento rápido de cápsulas",
"Point {0} taken, but there is no HQ — no pod will come":"Punto {0} tomado, pero no hay CG: no llegará ninguna cápsula",
"The bomber took off from the base — into the sky, it will come out over the target":"El bombardero despegó de la base: sube al cielo y saldrá sobre el objetivo",
"Strategist":"Estratega",
"Top view: base, orders, production":"Vista cenital: base, órdenes, producción",
"Camera over one squad, click orders, abilities 1–4":"Cámara sobre una escuadra, órdenes con clic, habilidades 1–4",
"Shooter":"Tirador",
"You fight yourself in first person":"Combates tú mismo en primera persona",
"Commander is hidden in Settings":"Comandante está oculto en Ajustes",
"No other squads":"No hay otras escuadras",
"Mode button at the top right: tap — next (Strategist → Commander → Shooter), hold — pick":"Botón de modo arriba a la derecha: toque — siguiente (Estratega → Comandante → Tirador), mantener — elegir",
"{0} cycles: Strategist → Commander → Shooter · Alt+1/2/3 — straight to a mode":"{0} rota: Estratega → Comandante → Tirador · Alt+1/2/3 — directo a un modo",
"Mode: {0}. Click or {1} — next; hold or RMB — pick; Alt+1/2/3 — direct":"Modo: {0}. Clic o {1} — siguiente; mantener o clic der. — elegir; Alt+1/2/3 — directo",
"Box":"Marco",
"All army":"Ejército",
"Builder":"Ingeniero",
"possess the selection (nothing selected — to battle)":"poseer la selección (sin selección, al combate)",
"mode cycle: Strategist → Commander → Shooter · Alt+1/2/3 — direct":"ciclo de modos: Estratega → Comandante → Tirador · Alt+1/2/3 — directo",
"strategy (the same key there possesses the selection)":"estrategia (allí la misma tecla posee la selección)",
"strategy (cycle: Strategist → Commander → Shooter; P / Alt+2 — straight to Commander)":"estrategia (ciclo: Estratega → Comandante → Tirador; P / Alt+2 — directo a Comandante)",
"\"Commander\" on phone (off — hide)":"“Comandante” en el móvil (no — ocultar)",
"One button, three modes: Strategist → Commander → Shooter. Top view of one squad, click orders, 4 abilities, squad switching, diving into the shooter and back":"Un botón, tres modos: Estratega → Comandante → Tirador. Vista cenital de una escuadra, órdenes con clic, 4 habilidades, cambio de escuadra, saltar al Tirador y volver",
"One button, three modes in a cycle: Strategist → Commander → Shooter. Press {0} or the mode button below (next to \"▶ Possess\") to get to Commander. Straight there — P or Alt+2.":"Un botón, tres modos en ciclo: Estratega → Comandante → Tirador. Pulsa {0} o el botón de modo de abajo (junto a “▶ Poseer”) para ir a Comandante. Directo: P o Alt+2.",
"Switch squads: {0} — the next one (closest to the fight first), a card on the left or the middle mouse button on a squad. The previous squad keeps its order.":"Cambia de escuadra: {0} — la siguiente (primero la más cercana al combate), una tarjeta a la izquierda o el botón central sobre una escuadra. La anterior mantiene su orden.",
"Next on the ladder is the Shooter: {0} or the mode button. Also: double LMB on a trooper or F. Wheel all the way in — third person.":"Lo siguiente en la escalera es el Tirador: {0} o el botón de modo. También: doble clic izq. en un soldado o F. Rueda a tope hacia dentro: tercera persona.",
"{0} in the shooter cycles on to the Strategist. Straight to Commander — P or Alt+2 (or hold the mode button and pick ⌖). Squad veterancy is kept: menu → \"My squads\".":"{0} en el Tirador sigue el ciclo hasta el Estratega. Directo a Comandante: P o Alt+2 (o mantén el botón de modo y elige ⌖). La veteranía se conserva: menú → “Mis escuadras”.",
"The mode button at the top right: tap — next mode in the cycle (Strategist → Commander → Shooter). Tap it to get to Commander ⌖. Hold — pick one of three.":"Botón de modo arriba a la derecha: toque — siguiente modo del ciclo (Estratega → Comandante → Tirador). Tócalo para ir a Comandante ⌖. Mantener — elegir uno de tres.",
"Tap another card on the left or ⇆ at the top — the next squad (closest to the fight first).":"Toca otra tarjeta a la izquierda o ⇆ arriba: la siguiente escuadra (primero la más cercana al combate).",
"Tap the mode button \"▶ Fight\" — next on the ladder, the Shooter. Or double-tap a trooper of the squad.":"Toca el botón de modo “▶ Al combate”: lo siguiente en la escalera, el Tirador. O doble toque en un soldado de la escuadra.",
"Hold the mode button — three icons appear — pick ⌖ Commander. (A plain tap cycles on to the Strategist.) Veterancy is kept: menu → \"My squads\".":"Mantén el botón de modo (salen tres iconos) y elige ⌖ Comandante. (Un toque normal sigue el ciclo hasta el Estratega.) La veteranía se conserva: menú → “Mis escuadras”.",
