"Pilot \"{0}\" rescued":"Piloto “{0}” rescatado",
"Thanks, guys! Grabbing a rifle — I am with you.":"¡Gracias, chicos! Cojo un fusil: voy con vosotros.",
"hero quest":"misión de héroe",
"here, a gun from the trunk — MG for 90 s":"toma, un arma del maletero: ametralladora 90 s",
