"Living world: requests, hero quests, breakthrough ops":"Mundo vivo: peticiones, misiones de héroe, operaciones de vuelco",
"Living world":"Mundo vivo",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Los tuyos piden ayuda y te recompensan, los héroes dan misiones y una operación rompe un frente estancado",
"A request":"Una petición",
"Breakthrough":"Vuelco",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"A veces los tuyos piden ayuda: llamada por radio, una tarjeta PETICIÓN y un marcador ✋. Una escuadra está inmovilizada: destruye a los enemigos cercanos. Recompensa: un soldado en cápsula desde la base, un arma del maletero de un buggy, el puesto de artillero o cobertura orbital. ¿Ahora no? ✕ o ignóralo.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"El explorador veterano “Búho” ofrece una misión. Y — aceptar (N — rechazar). Ve al marcador ★, elimina a los guardias y quédate 3 s junto al piloto: se une a tu escuadra.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"El frente se estancó: el CG propone un vuelco. Y — aceptar. Mantén el repetidor 8 s sin enemigos cerca: mapa enemigo visible 60 s. El generador: torretas enemigas calladas 2 min. En Estratega: “Asignar escuadra”. El enemigo también puede: atento a ⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Los tuyos piden ayuda: una tarjeta PETICIÓN y un marcador ✋. Destruye a los enemigos junto a la escuadra inmovilizada y recibe una recompensa. ✕ — omitir.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"El héroe “Búho” ofrece una misión: toca “Aceptar”. Ve a ★, elimina a los guardias y quédate junto al piloto.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"El frente se estancó: toca “Aceptar” y mantén el repetidor 8 s; el mapa enemigo se abre un minuto.",
"Pod redeploy from the base: {0} m — through the sky portal":"Redespliegue en cápsula desde la base: {0} m, por el portal celeste",
"Pod away from the base! Hold on — exit over the target.":"¡Cápsula fuera de la base! Agárrate: salida sobre el objetivo.",
"Landed at the objective!":"¡Aterrizaje en el objetivo!",
"LAUNCH FROM BASE":"LANZAMIENTO DESDE BASE",
"LANDING":"ATERRIZAJE",
"REDEPLOY":"REDESPLIEGUE",
"Steel fluff stuck to you — corrodes armour −2/s. Stand still 3 s out of combat or find an engineer":"Se te pegó pelusa de acero: corroe el blindaje −2/s. Quédate quieto 3 s fuera de combate o busca un ingeniero",
"An engineer brushed the fluff off":"Un ingeniero te quitó la pelusa",
"The fluff fell off — armour is safe":"La pelusa se cayó: el blindaje está a salvo",
"The firefly swarm scattered by the blast":"El enjambre de luciérnagas se dispersó con la explosión",
"STEEL FLUFF −2/s · stand still 3 s or find an engineer":"PELUSA DE ACERO −2/s · quieto 3 s o busca un ingeniero",
"Lefty's convoy is ready: two Jackals. Stay close — they wait for you":"El convoy de Zurdo está listo: dos Chacales. Mantente cerca: te esperan",
"The convoy is waiting for you":"El convoy te espera",
