"Consortium: builders place \"Concrete barriers\" and a \"Repair post\"; turrets are cheaper and tougher, builders repair vehicles on their own.":"Consórcio: engenheiros colocam “Barreiras de concreto” e um “Posto de reparo”; torretas mais baratas e resistentes, engenheiros consertam veículos sozinhos.",
