"Faster pod launches":"Lançamento rápido de cápsulas",
"Point {0} taken, but there is no HQ — no pod will come":"Ponto {0} tomado, mas não há QG — nenhuma cápsula virá",
"The bomber took off from the base — into the sky, it will come out over the target":"O bombardeiro decolou da base — sobe ao céu e sairá sobre o alvo",
"Strategist":"Estrategista",
"Top view: base, orders, production":"Visão de cima: base, ordens, produção",
"Camera over one squad, click orders, abilities 1–4":"Câmera sobre um esquadrão, ordens com clique, habilidades 1–4",
