"Commander is hidden in Settings":"Comandante está oculto em Configurações",
"No other squads":"Não há outros esquadrões",
"Mode button at the top right: tap — next (Strategist → Commander → Shooter), hold — pick":"Botão de modo no canto superior direito: toque — próximo (Estrategista → Comandante → Atirador), segurar — escolher",
"{0} cycles: Strategist → Commander → Shooter · Alt+1/2/3 — straight to a mode":"{0} alterna: Estrategista → Comandante → Atirador · Alt+1/2/3 — direto para um modo",
"Mode: {0}. Click or {1} — next; hold or RMB — pick; Alt+1/2/3 — direct":"Modo: {0}. Clique ou {1} — próximo; segurar ou clique dir. — escolher; Alt+1/2/3 — direto",
"Box":"Caixa",
"All army":"Exército",
"Builder":"Engenheiro",
"possess the selection (nothing selected — to battle)":"possuir a seleção (sem seleção — para o combate)",
"mode cycle: Strategist → Commander → Shooter · Alt+1/2/3 — direct":"ciclo de modos: Estrategista → Comandante → Atirador · Alt+1/2/3 — direto",
"strategy (the same key there possesses the selection)":"estratégia (lá a mesma tecla possui a seleção)",
"strategy (cycle: Strategist → Commander → Shooter; P / Alt+2 — straight to Commander)":"estratégia (ciclo: Estrategista → Comandante → Atirador; P / Alt+2 — direto ao Comandante)",
"\"Commander\" on phone (off — hide)":"“Comandante” no celular (desl. — ocultar)",
"One button, three modes: Strategist → Commander → Shooter. Top view of one squad, click orders, 4 abilities, squad switching, diving into the shooter and back":"Um botão, três modos: Estrategista → Comandante → Atirador. Visão de cima de um esquadrão, ordens com clique, 4 habilidades, troca de esquadrão, mergulho no Atirador e volta",
"One button, three modes in a cycle: Strategist → Commander → Shooter. Press {0} or the mode button below (next to \"▶ Possess\") to get to Commander. Straight there — P or Alt+2.":"Um botão, três modos em ciclo: Estrategista → Comandante → Atirador. Aperte {0} ou o botão de modo embaixo (ao lado de “▶ Possuir”) para ir ao Comandante. Direto — P ou Alt+2.",
"Switch squads: {0} — the next one (closest to the fight first), a card on the left or the middle mouse button on a squad. The previous squad keeps its order.":"Troque de esquadrão: {0} — o próximo (primeiro o mais perto do combate), um cartão à esquerda ou o botão do meio num esquadrão. O anterior mantém a ordem.",
"Next on the ladder is the Shooter: {0} or the mode button. Also: double LMB on a trooper or F. Wheel all the way in — third person.":"O próximo na escada é o Atirador: {0} ou o botão de modo. Também: clique duplo num soldado ou F. Roda toda para dentro — terceira pessoa.",
"{0} in the shooter cycles on to the Strategist. Straight to Commander — P or Alt+2 (or hold the mode button and pick ⌖). Squad veterancy is kept: menu → \"My squads\".":"{0} no Atirador segue o ciclo até o Estrategista. Direto ao Comandante — P ou Alt+2 (ou segure o botão de modo e escolha ⌖). A veterania se mantém: menu → “Meus esquadrões”.",
"The mode button at the top right: tap — next mode in the cycle (Strategist → Commander → Shooter). Tap it to get to Commander ⌖. Hold — pick one of three.":"Botão de modo no canto superior direito: toque — próximo modo do ciclo (Estrategista → Comandante → Atirador). Toque para ir ao Comandante ⌖. Segurar — escolher um dos três.",
"Tap another card on the left or ⇆ at the top — the next squad (closest to the fight first).":"Toque em outro cartão à esquerda ou em ⇆ no topo — o próximo esquadrão (primeiro o mais perto do combate).",
"Tap the mode button \"▶ Fight\" — next on the ladder, the Shooter. Or double-tap a trooper of the squad.":"Toque no botão de modo “▶ Combate” — o próximo na escada, o Atirador. Ou toque duplo num soldado do esquadrão.",
"Hold the mode button — three icons appear — pick ⌖ Commander. (A plain tap cycles on to the Strategist.) Veterancy is kept: menu → \"My squads\".":"Segure o botão de modo — aparecem três ícones — escolha ⌖ Comandante. (Um toque simples segue o ciclo até o Estrategista.) A veterania se mantém: menu → “Meus esquadrões”.",
