"Living world":"Mundo vivo",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Os seus pedem ajuda e recompensam, heróis dão missões e uma operação quebra uma frente travada",
"A request":"Um pedido",
"Breakthrough":"Virada",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Às vezes os seus pedem ajuda: chamada no rádio, um cartão PEDIDO e um marcador ✋. Um esquadrão está encurralado — destrua os inimigos perto dele. Recompensa: um soldado por cápsula da base, uma arma da caçamba de um buggy, o posto de atirador ou cobertura orbital. Agora não — ✕ ou simplesmente ignore.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"O batedor veterano “Coruja” oferece uma missão. Y — aceitar (N — recusar). Vá ao marcador ★, elimine os guardas e fique 3 s ao lado do piloto — ele entra no seu esquadrão.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"A frente travou — o QG propõe uma virada. Y — aceitar. Segure o repetidor por 8 s sem inimigos perto: o mapa inimigo fica visível por 60 s. O gerador — torretas inimigas caladas por 2 min. No Estrategista — “Atribuir esquadrão”. O inimigo também pode: fique de olho no ⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Os seus pedem ajuda: um cartão PEDIDO e um marcador ✋. Destrua os inimigos perto do esquadrão encurralado — ganhe uma recompensa. ✕ — pular.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"O herói “Coruja” oferece uma missão — toque em “Aceitar”. Vá até ★, elimine os guardas, fique perto do piloto.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"A frente travou — toque em “Aceitar” e segure o repetidor por 8 s: o mapa inimigo abre por um minuto.",
