"Repairs others":"Repara os outros",
"Builds structures and extractors, repairs, cleans Steel fluff off others.":"Constrói edifícios e extratores, repara e limpa a Penugem de aço dos outros.",
"A squad flies from the base launch pad through the sky portal right to the target.":"Um esquadrão voa da plataforma de lançamento da base pelo portal celeste direto ao alvo.",
"Squad: ":"Esquadrão: ",
"Engineer":"Engenheiro",
"Infantry":"Infantaria",
"Members: ":"Membros: ",
"Main battle tank: cannon and MG. Consortium \"Bulldog\" is tougher, Swarm \"Spider\" is faster.":"Tanque principal: canhão e metralhadora. O “Buldogue” do Consórcio é mais resistente; a “Aranha” do Enxame, mais rápida.",
"Heavy tank":"Tanque pesado",
"Drone":"Drone",
"Autonomous flying gunner: fast, fragile, fears anti-air.":"Atirador voador autônomo: rápido, frágil, teme a antiaérea.",
"Upgrade":"Melhoria",
"Drones":"Drones",
"Longer, faster jetpacks for all infantry.":"Jetpacks mais longos e rápidos para toda a infantaria.",
"Extractors mine more ore.":"Os extratores mineram mais minério.",
"Army-wide levels: less damage taken / more damage dealt.":"Níveis para todo o exército: menos dano recebido / mais dano causado.",
"Levels":"Níveis",
"Base":"Base",
"Heart of the base: squads, engineers, pods, research. Lose it and you lose.":"O coração da base: esquadrões, engenheiros, cápsulas, pesquisa. Perdeu, perdeu a partida.",
"Produces: ":"Produz: ",
"Launch pad":"Plataforma de lançamento",
"A silo next to the HQ: pods, supply crates and bombers launch from here through the sky portal. Nothing can be built on it.":"Um silo ao lado do QG: cápsulas, caixas de suprimentos e bombardeiros decolam daqui pelo portal celeste. Não dá para construir nele.",
"Economy":"Economia",
"Key building":"Edifício-chave",
"Building":"Edifício",
"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"Ponto fraco — a traseira (motor): dano ×{0}. Canhão, 2 torres de metralhadora, lança-foguetes; gira muito devagar — flanqueie.",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"Ponto fraco — o núcleo brilhante sob o ventre: dano por baixo ×{0}. Raio de distorção e pisão em área; passa por cima de barreiras — mantenha distância, não se amontoe.",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"Contra ele: bombas e artilharia (×{0}), foguetes (×{1}), bombardeio em tapete; balas quase não fazem efeito (×{2}).",
"Faction":"Facção",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"Máquinas rápidas, bandos de drones, túneis e regeneração. Infantaria mais leve, porém mais rápida; canhões e trilhos batem mais forte.",
"Heavy power-armoured infantry, concrete barriers, repair and artillery. Slower but tougher.":"Infantaria pesada com servoarmadura, barreiras de concreto, reparo e artilharia. Mais lenta, porém mais resistente.",
"Infantry HP":"Infantaria: blindagem",
"Infantry speed":"Infantaria: velocidade",
