"Commander: regen burst, jet leap.":"Comandante: surto de regeneração, salto de jetpack.",
"Commander: field medic, mini barrier.":"Comandante: médico de campo, minibarreira.",
"Wave 1 · v7.8":"Onda 1 · v7.8",
