"Consortium: builders place \"Concrete barriers\" and a \"Repair post\"; turrets are cheaper and tougher, builders repair vehicles on their own.":"קונסורציום: מהנדסים מציבים “מחסומי בטון” ו“עמדת תיקון”; צריחים זולים וחזקים יותר, והמהנדסים מתקנים כלי רכב בעצמם.",
