"Consortium builders repair nearby vehicles and buildings on their own (up to 70–80 m), 1.3× faster.":"מהנדסי הקונסורציום מתקנים בעצמם כלי רכב ומבנים סמוכים (עד 70–80 מ׳), פי 1.3 מהר יותר.",
