"The \"Incubator\" is unlocked: it grows the \"Reaper\" walker — one per army. Its weak spot is the glowing core underneath.":"‏“המדגרה” נפתחה: בה גדל המהלך “הקוצר” — אחד לצבא. נקודת התורפה שלו — הליבה הזוהרת מלמטה.",
