"Veterancy carries over between battles. A squad earns XP (infantry 1, building 2, vehicle 3), levels, stars and perks. Veterans deploy first in a new battle. A lost squad loses everything and joins the Fallen.":"הוותק נשמר בין קרבות. החוליה צוברת נ״ן (חי״ר 1, מבנה 2, כלי רכב 3), רמות, כוכבים ויתרונות. בקרב חדש הוותיקים נכנסים ראשונים. חוליה שנפלה מאבדת הכול ועוברת ל“הנופלים”.",
