"Field medic":"חובש שדה",
"+20% hull to all at once, then 4 s of repair.":"‏‎+20% חוזק לכולם מיד, ואז 4 שנ׳ של תיקון.",
"Regen burst":"פרץ התחדשות",
"Swarm: 8 s of fast regeneration for the whole squad.":"הנחיל: 8 שנ׳ של התחדשות מהירה לכל החוליה.",
"Grenade volley":"מטח רימונים",
"Every trooper throws a grenade at the point.":"כל לוחם זורק רימון אל הנקודה.",
"AT rocket":"רקטת נ״ט",
"Heavy rockets at a vehicle or building (up to 3).":"רקטות כבדות על כלי רכב או מבנה (עד 3).",
"Jet leap":"זינוק סילון",
"The squad jet-leaps to a point (up to 80 m).":"החוליה מזנקת בסילון אל נקודה (עד 80 מ׳).",
"Mini barrier":"מיני-מחסום",
