"No squads to command — order a squad":"אין חוליות לפקד עליהן — הזמן חוליה",
"Commander: {0}. LMB — move / attack, 1–4 — abilities, Tab — next squad, double-click a trooper — fight, P — strategy":"מפקד: {0}. קליק שמאלי — תנועה / תקיפה, 1–4 — יכולות, Tab — חוליה אחרת, לחיצה כפולה על לוחם — לקרב, P — אסטרטגיה",
"Tap — move/attack, double-tap a trooper — fight, right buttons — abilities":"הקשה — תנועה/תקיפה, הקשה כפולה על לוחם — לקרב, כפתורים מימין — יכולות",
