"Fight":"לקרב",
"Tap a point on the map (or the same button to cancel)":"הקש על נקודה במפה (או על אותו כפתור לביטול)",
"LMB — where to use · same key — at cursor · RMB / Esc — cancel":"קליק שמאלי — היכן להפעיל · אותו מקש — בסמן העכבר · קליק ימני / Esc — ביטול",
"Tap — move / attack · double-tap a trooper — fight · drag — rotate, pinch — zoom":"הקשה — תנועה / תקיפה · הקשה כפולה על לוחם — לקרב · גרירה — סיבוב, צביטה — זום",
"LMB — move / attack (2× run) · double-click a trooper — fight · Tab — squad · Q/E, wheel — camera · H — hold":"קליק שמאלי — תנועה / תקיפה (2× ריצה) · לחיצה כפולה על לוחם — לקרב · Tab — חוליה · Q/E, גלגלת — מצלמה · H — החזק עמדה",
"Commander":"מפקד",
"Commander mode: top view of one squad, abilities 1–4":"מצב מפקד: מבט מלמעלה על חוליה אחת, יכולות 1–4",
"Top view of your squad: click orders, abilities 1–4.":"מבט מלמעלה על החוליה שלך: פקודות בקליק, יכולות 1–4.",
"Hold position":"החזק עמדה",
"The third mode: top view of one squad, click orders, 4 abilities, squad switching, diving into the shooter and back":"המצב השלישי: מבט מלמעלה על חוליה אחת, פקודות בקליק, 4 יכולות, החלפת חוליה, צלילה ליורה וחזרה",
"SQUAD":"חוליה",
"Commander mode":"מצב מפקד",
"Move in formation":"תנועה במבנה",
"Squad ability":"יכולת חוליה",
"Another squad":"חוליה אחרת",
"Dive into the shooter":"צלילה ליורה",
"Back to Commander":"חזרה למפקד",
"Turn on the third mode, Commander: the P key or the \"⌖ Commander\" button at the bottom next to \"▶ Possess\". The camera drops to the squad — 27 m above it, at an angle.":"הפעל את המצב השלישי, מפקד: מקש P או הכפתור “⌖ מפקד” למטה, ליד “▶ השתלט”. המצלמה יורדת אל החוליה — 27 מ׳ מעליה, בזווית.",
"LMB on the \"HERE\" marker — the squad moves there in formation. LMB on an enemy — attack, double LMB on the ground — run. Q/E and the wheel — camera.":"קליק שמאלי על הסמן “לכאן” — החוליה נעה במבנה. קליק שמאלי על אויב — תקיפה, לחיצה כפולה על הקרקע — ריצה. Q/E והגלגלת — מצלמה.",
"Four squad abilities — keys 1–4 or the buttons below. Smoke, sprint and suppression — then LMB on a point (the same key again — at the cursor). Medic — instantly.":"ארבע יכולות חוליה — מקשים 1–4 או הכפתורים למטה. עשן, ספרינט ודיכוי — ואז קליק שמאלי על נקודה (אותו מקש שוב — בסמן העכבר). חובש — מיד.",
"Switch squads: Tab, a card on the left or the middle mouse button on a squad. The previous squad carries on with its last order.":"החלף חוליה: Tab, כרטיס משמאל או לחצן העכבר האמצעי על חוליה. החוליה הקודמת ממשיכה בפקודה האחרונה.",
"Double LMB on a trooper of your squad (or F, \"▶ Fight\") — dive into the shooter. Wheel all the way in — into the trooper in third person.":"לחיצה כפולה על לוחם מהחוליה שלך (או F, “▶ לקרב”) — צלילה ליורה. גלגלת עד הסוף פנימה — אל הלוחם בגוף שלישי.",
"{0} in the shooter — back to Commander over the same squad; P — to the Strategist. Squad veterancy carries over between battles: menu → \"My squads\".":"‏{0} במצב יורה — חזרה למפקד מעל אותה חוליה; P — לאסטרטג. הוותק של החוליות נשמר בין קרבות: תפריט ← “החוליות שלי”.",
"Tap ⌖ at the top right — Commander mode. On a phone turn it on in Settings (\"Commander mode on phone\"); in the lesson it is already on.":"הקש ⌖ למעלה מימין — מצב מפקד. בטלפון מפעילים אותו בהגדרות (“מצב מפקד בטלפון”); בשיעור הוא כבר פעיל.",
"Tap the \"HERE\" marker — the squad moves in formation. Tap an enemy — attack. Drag — rotate the camera, pinch — zoom.":"הקש על הסמן “לכאן” — החוליה נעה במבנה. הקש על אויב — תקיפה. גרירה — סיבוב המצלמה, צביטה — זום.",
"The round buttons at the bottom right are 4 abilities. Smoke, sprint, suppression — then tap a point on the map.":"הכפתורים העגולים למטה מימין — 4 יכולות. עשן, ספרינט, דיכוי — ואז הקש על נקודה במפה.",
"Tap another card on the left — the camera flies to that squad.":"הקש על כרטיס אחר משמאל — המצלמה עפה אל החוליה ההיא.",
"Double-tap a trooper of the squad or \"▶ Fight\" — dive into the shooter.":"הקשה כפולה על לוחם מהחוליה או “▶ לקרב” — צלילה ליורה.",
"\"◩ Strategy\" in the shooter brings you back to Commander over the same squad. Squad veterancy carries over: menu → \"My squads\".":"‏“◩ אסטרטגיה” במצב יורה מחזיר אותך למפקד מעל אותה חוליה. הוותק נשמר: תפריט ← “החוליות שלי”.",
"❄ Frozen by coolant: −60% speed, explosions hurt more (8 s)":"‏❄ קפוא מנוזל קירור: ‎−60% מהירות, פיצוצים פוגעים יותר (8 שנ׳)",
"⤒ Dislocation! The sky portal is pulling you up…":"‏⤒ נקע! שער השמיים מושך אותך למעלה…",
"⤓ Exit at the antipode — disoriented for 2 s":"‏⤓ יציאה באנטיפוד — בלבול ל־2 שנ׳",
"anomaly discharged":"האנומליה נפרקה",
"discharged, dormant for":"נפרקה, רדומה למשך",
"CP":"נק״פ",
"DISLOCATION EXIT":"יציאת הנקע",
"m":"מ׳",
