"Draught":"משב רוח",
"Muffler":"משתיק",
"Anomaly! Dust falling upwards — a Dislocation, it will pull you into the sky!":"אנומליה! אבק נופל כלפי מעלה — נקע, הוא יסחוף אותך לשמיים!",
"Dislocation ahead — step in and you come out on the other side of the meteor!":"נקע לפנים — מי שנכנס יוצא בצד השני של המטאוריט!",
"Anomaly — the picture breaks into pixels! A Mosaic, aim goes wild!":"אנומליה — התמונה מתפרקת לפיקסלים! פסיפס, הכוונת משתוללת!",
"Pixel square — go around, everything jerks in there.":"ריבוע פיקסלים — עוקפים, בפנים הכול קופץ.",
"Frost on the ground — a coolant geyser! It will freeze you!":"כפור על הקרקע — גייזר קירור! הוא יקפיא אותך!",
"Hear the hiss? Geyser, back off!":"שומע את השריקה? גייזר, סגת!",
"A strip of haze — a Draught, it blows even rockets away!":"רצועת אובך — משב רוח, הוא מסיט אפילו רקטות!",
"Draught ahead, hold on!":"משב רוח לפנים, תחזיק חזק!",
"Grey static — a Muffler! We lose the radio in there!":"רעש סטטי אפור — משתיק! שם נאבד את הקשר!",
"Muffler ahead: no radio, no support.":"משתיק לפנים: אין קשר ואין סיוע.",
"Muffler: no signal":"משתיק: אין קליטה",
"Wasteland":"שממה",
"Green anomalous zone":"האזור החריג הירוק",
"Russet belt":"החגורה האדמונית",
"White cap":"הכיפה הלבנה",
"grass hides infantry: unseen beyond 40 m unless firing":"הדשא מסתיר חי״ר: לא נראה מעבר ל־40 מ׳ אלא אם יורה",
"leaves rustle: runners are heard 32 m away":"העלים מרשרשים: שומעים רצים ממרחק 32 מ׳",
"snow: infantry −15% speed, sight ×0.7":"שלג: חי״ר ‎−15% מהירות, ראות ‎×0.7",
