"Sporecap":"כובע-נבגים",
"Shellback":"גב-שריון",
"Tristrider":"תלת-רגל",
"the Verdan is angry!":"הוורדן התרגז!",
"Verdan":"ורדן",
"destroyed, a spray of green sap":"הושמד, ניתז מיץ ירוק",
"ANGRY":"כועס",
"A Verdan! This plant bites!":"ורדן! הצמח הזה נושך!",
"Don't touch the plants — they get angry!":"אל תיגעו בצמחים — הם מתרגזים!",
"Biomes and anomalies":"ביומות ואנומליות",
"Green grass hides infantry, sharp biome borders, the Dislocation throws you to the antipode, Verdans are neutral until provoked":"דשא ירוק מסתיר חי״ר, גבולות ביומה חדים, הנקע זורק אותך לאנטיפוד, הוורדנים ניטרליים עד שמתגרים בהם",
"GRASS":"דשא",
"ACROSS":"מעבר לגבול",
"DISLOCATION":"נקע",
"VERDAN":"ורדן",
"Green zone":"האזור הירוק",
"Sharp border":"גבול חד",
"The meteor now has biomes: green grass, russet autumn, snow — with sharp borders. Walk to the \"GRASS\" marker. In the green zone grass hides infantry: enemies beyond 40 m cannot see you unless you fire.":"למטאוריט יש עכשיו ביומות: דשא ירוק, סתיו אדמוני, שלג — עם גבולות חדים. לך לסמן “דשא”. באזור הירוק הדשא מסתיר חי״ר: אויבים מעבר ל־40 מ׳ לא רואים אותך אלא אם אתה יורה.",
"Cross the border to the marker. In the Russet belt footsteps are louder (runners are heard 32 m away), in the White cap infantry is 15% slower and sight is ×0.7.":"חצה את הגבול אל הסמן. בחגורה האדמונית הצעדים רועשים יותר (שומעים רצים מ־32 מ׳), בכיפה הלבנה החי״ר איטי ב־15% והראות ‎×0.7.",
"Second-wave anomalies. The Dislocation — dust falls upwards. Step in: the sky portal takes you and ~5 s later you exit at the antipode (both teams see the exit). Also: Mosaic (pixels, spread), Geyser (freeze), Draught (pushes), Muffler (no radio). A bolt (E) or a grenade discharges an anomaly.":"אנומליות מהגל השני. הנקע — אבק נופל כלפי מעלה. היכנס: שער השמיים לוקח אותך ואחרי ~5 שנ׳ אתה יוצא באנטיפוד (שתי הקבוצות רואות את היציאה). וגם: פסיפס (פיקסלים, פיזור), גייזר (הקפאה), משב רוח (דוחף), משתיק (אין קשר). בורג (E) או רימון פורקים אנומליה.",
"A Verdan is a living alien plant. It is neutral until you touch it or come close, but dangerous to both factions. This one is a Sporecap: destroy it from range (LMB) without walking into the spore cloud. Fire burns Verdans harder.":"ורדן הוא צמח חייזרי חי. הוא ניטרלי עד שנוגעים בו או מתקרבים, אך מסוכן לשני הפלגים. זה כובע-נבגים: השמד אותו מרחוק (קליק שמאלי) בלי להיכנס לענן הנבגים. אש שורפת ורדנים חזק יותר.",
"The meteor now has biomes with sharp borders. Use the stick to walk to the \"GRASS\" marker. Grass hides infantry beyond 40 m unless you fire.":"למטאוריט יש עכשיו ביומות עם גבולות חדים. בעזרת הג׳ויסטיק לך לסמן “דשא”. הדשא מסתיר חי״ר מעבר ל־40 מ׳ אלא אם אתה יורה.",
"Cross the border to the marker. Autumn — louder steps, snow — slower and worse sight.":"חצה את הגבול אל הסמן. סתיו — צעדים רועשים יותר, שלג — איטי יותר וראות גרועה.",
"The Dislocation — dust falls upwards. Step in: it lifts you to the sky and ~5 s later drops you at the antipode. The ⏏ button near an anomaly throws a bolt to discharge it.":"הנקע — אבק נופל כלפי מעלה. היכנס: הוא מרים אותך לשמיים ואחרי ~5 שנ׳ מפיל אותך באנטיפוד. הכפתור ⏏ ליד אנומליה זורק בורג כדי לפרוק אותה.",
"A Verdan is neutral until you come close. Destroy the Sporecap from range — shoot.":"ורדן ניטרלי עד שמתקרבים. השמד את כובע-הנבגים מרחוק — ירה.",
