"Faster pod launches":"שיגור קפסולות מהיר יותר",
"Point {0} taken, but there is no HQ — no pod will come":"נקודה {0} נכבשה, אבל אין מפקדה — שום קפסולה לא תגיע",
"The bomber took off from the base — into the sky, it will come out over the target":"המפציץ המריא מהבסיס — עולה לשמיים, ויופיע מעל המטרה",
