"Commander is hidden in Settings":"המפקד מוסתר בהגדרות",
"No other squads":"אין חוליות אחרות",
"Mode button at the top right: tap — next (Strategist → Commander → Shooter), hold — pick":"כפתור המצב למעלה מימין: הקשה — הבא (אסטרטג ← מפקד ← יורה), החזקה — בחירה",
"{0} cycles: Strategist → Commander → Shooter · Alt+1/2/3 — straight to a mode":"‏{0} מחליף במעגל: אסטרטג ← מפקד ← יורה · Alt+1/2/3 — ישר למצב",
"Mode: {0}. Click or {1} — next; hold or RMB — pick; Alt+1/2/3 — direct":"מצב: {0}. קליק או {1} — הבא; החזקה או קליק ימני — בחירה; Alt+1/2/3 — ישירות",
"Box":"מסגרת",
"All army":"כל הצבא",
"Builder":"מהנדס",
"possess the selection (nothing selected — to battle)":"השתלט על הנבחר (אם לא נבחר דבר — לקרב)",
"mode cycle: Strategist → Commander → Shooter · Alt+1/2/3 — direct":"מחזור מצבים: אסטרטג ← מפקד ← יורה · Alt+1/2/3 — ישירות",
"strategy (the same key there possesses the selection)":"אסטרטגיה (שם אותו מקש משתלט על הנבחר)",
"strategy (cycle: Strategist → Commander → Shooter; P / Alt+2 — straight to Commander)":"אסטרטגיה (מחזור: אסטרטג ← מפקד ← יורה; P / Alt+2 — ישר למפקד)",
"\"Commander\" on phone (off — hide)":"‏“מפקד” בטלפון (כבוי — הסתרה)",
"One button, three modes: Strategist → Commander → Shooter. Top view of one squad, click orders, 4 abilities, squad switching, diving into the shooter and back":"כפתור אחד, שלושה מצבים: אסטרטג ← מפקד ← יורה. מבט מלמעלה על חוליה, פקודות בקליק, 4 יכולות, החלפת חוליה, צלילה ליורה וחזרה",
"One button, three modes in a cycle: Strategist → Commander → Shooter. Press {0} or the mode button below (next to \"▶ Possess\") to get to Commander. Straight there — P or Alt+2.":"כפתור אחד, שלושה מצבים במעגל: אסטרטג ← מפקד ← יורה. לחץ {0} או על כפתור המצב למטה (ליד “▶ השתלט”) כדי להגיע למפקד. ישירות — P או Alt+2.",
"Switch squads: {0} — the next one (closest to the fight first), a card on the left or the middle mouse button on a squad. The previous squad keeps its order.":"החלף חוליה: {0} — הבאה (קודם הקרובה ביותר לקרב), כרטיס משמאל או לחצן אמצעי על חוליה. החוליה הקודמת שומרת על הפקודה שלה.",
"Next on the ladder is the Shooter: {0} or the mode button. Also: double LMB on a trooper or F. Wheel all the way in — third person.":"הבא בסולם הוא היורה: {0} או כפתור המצב. וגם: לחיצה כפולה על לוחם או F. גלגלת עד הסוף פנימה — גוף שלישי.",
"{0} in the shooter cycles on to the Strategist. Straight to Commander — P or Alt+2 (or hold the mode button and pick ⌖). Squad veterancy is kept: menu → \"My squads\".":"‏{0} במצב יורה ממשיך במעגל אל האסטרטג. ישר למפקד — P או Alt+2 (או החזק את כפתור המצב ובחר ⌖). הוותק נשמר: תפריט ← “החוליות שלי”.",
"The mode button at the top right: tap — next mode in the cycle (Strategist → Commander → Shooter). Tap it to get to Commander ⌖. Hold — pick one of three.":"כפתור המצב למעלה מימין: הקשה — המצב הבא במעגל (אסטרטג ← מפקד ← יורה). הקש כדי להגיע למפקד ⌖. החזקה — בחירה אחד משלושה.",
"Tap another card on the left or ⇆ at the top — the next squad (closest to the fight first).":"הקש על כרטיס אחר משמאל או על ⇆ למעלה — החוליה הבאה (קודם הקרובה ביותר לקרב).",
"Tap the mode button \"▶ Fight\" — next on the ladder, the Shooter. Or double-tap a trooper of the squad.":"הקש על כפתור המצב “▶ לקרב” — הבא בסולם, היורה. או הקשה כפולה על לוחם מהחוליה.",
"Hold the mode button — three icons appear — pick ⌖ Commander. (A plain tap cycles on to the Strategist.) Veterancy is kept: menu → \"My squads\".":"החזק את כפתור המצב — יופיעו שלושה סמלים — בחר ⌖ מפקד. (הקשה רגילה ממשיכה במעגל אל האסטרטג.) הוותק נשמר: תפריט ← “החוליות שלי”.",
