"Select a unit → \"▶ Possess\" or double-click. {0} cycles: Strategist → Commander → Shooter.":"בחר יחידה ← “▶ השתלט” או לחיצה כפולה. {0} מחליף במעגל: אסטרטג ← מפקד ← יורה.",
