"At the top is the strategist's order: follow it, XP ×2–×3":"למעלה — פקודת האסטרטג: בצע אותה, נ״ן ‎×2–‎×3",
"{0} — jump pack: tap to hop, hold to fly":"‏{0} — תרמיל סילון: הקשה — קפיצה, החזקה — טיסה",
"{0} in the air — jet brake":"‏{0} באוויר — בלימת סילון",
"{0} while running — slide · jump at a wall — wall-jump":"‏{0} בזמן ריצה — החלקה · קפיצה ליד קיר — ניתור מהקיר",
"Bullets hit hardest at 20–50 m":"הקליעים חזקים ביותר ב־20–50 מ׳",
