"{0} next to our tank — take it":"‏{0} ליד הטנק שלנו — עלה עליו",
"{0} next to the turret — man it":"‏{0} ליד הצריח — אייש אותו",
"Quiet here — {0}: a unit closer to the fight":"שקט כאן — {0}: יחידה קרובה יותר לקרב",
"You run faster along the strategist's green chevrons":"אתה רץ מהר יותר לאורך החיצים הירוקים של האסטרטג",
