"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"החברים מבקשים עזרה ומתגמלים, גיבורים נותנים משימות, וחזית תקועה נפרצת במבצע",
"A request":"בקשת עזרה",
"Breakthrough":"תפנית",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"לפעמים החברים מבקשים עזרה: קריאה בקשר, כרטיס “בקשה” וסמן ✋. חוליה מרותקת — השמד את האויבים לידה. פרס: לוחם בקפסולה מהבסיס, נשק מתא המטען של באגי, עמדת התותחן או חיפוי מהמסלול. לא עכשיו — ✕ או פשוט התעלם.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"הסייר הוותיק “ינשוף” מציע משימה. Y — קבל (N — דחה). לך לסמן ★, חסל את השומרים ועמוד ליד הטייס 3 שנ׳ — הוא יצטרף לחוליה שלך.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"החזית נתקעה — המפקדה מציעה תפנית. Y — קבל. החזק את הממסר 8 שנ׳ בלי אויבים בקרבת מקום: מפת האויב גלויה 60 שנ׳. הגנרטור — צריחי האויב שותקים 2 דק׳. במצב אסטרטג — “הקצה חוליה”. גם האויב יכול: שים לב ל־⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"החברים מבקשים עזרה: כרטיס “בקשה” וסמן ✋. השמד את האויבים ליד החוליה המרותקת — קבל פרס. ✕ — דלג.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"הגיבור “ינשוף” מציע משימה — הקש “קבל”. לך ל־★, חסל את השומרים, עמוד ליד הטייס.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"החזית נתקעה — הקש “קבל” והחזק את הממסר 8 שנ׳: מפת האויב תיפתח לדקה.",
