const V8X = {
  // коды языков v7.9 -> коды словаря (подправь под v7.9, если там другие)
  ALIAS: { tj: 'tg', tgk: 'tg', pt: 'pt-BR', ptbr: 'pt-BR', pt_BR: 'pt-BR', 'pt-br': 'pt-BR', 'zh-CN': 'zh', 'zh-Hans': 'zh', zh_CN: 'zh', iw: 'he', 'uz-Latn': 'uz' },
  VI_FULL: false,    // true — для vi брать полные тексты vi_full вместо сокращённых из кода
  HE_OVER_AUTO: true, // true — для he наш перевод важнее автоматического HE68 (если he не передан в tr)
  C: {},             // кэш по языкам: { map, tpl, cache }
  code(L){ L = L || (typeof LANG !== 'undefined' ? LANG.cur : ''); return this.ALIAS[L] || L; },
  build(D){
    const C = { map: new Map(), tpl: [], cache: new Map() };
    for (const k in D){
      if (!/\{\d+\}/.test(k)){ C.map.set(k, D[k]); continue; }
      const lits = k.split(/\{\d+\}/), lit = lits.join('');
      if (lit.replace(/[^A-Za-zА-Яа-яЁё]/g, '').length < 3) continue;
      const order = (k.match(/\{\d+\}/g) || []).map(x => +x.slice(1, -1));
      const re = new RegExp('^' + lits.map(s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('([\\s\\S]*?)') + '$');
      C.tpl.push({ re, order, v: D[k], key: lits.reduce((a, b) => a.length >= b.length ? a : b, ''), n: lit.length });
    }
    C.tpl.sort((a, b) => b.n - a.n);
    return C;
  },
  // перевод английского текста en на язык L; undefined — нет в словаре
  get(L, en){
    if (typeof en !== 'string' || !en) return undefined;
    L = this.code(L);
    const D = V8X_DICT[L]; if (!D) return undefined;
    const C = this.C[L] || (this.C[L] = this.build(D));
    const m0 = C.map.get(en); if (m0 !== undefined) return m0;
    if (C.cache.has(en)) return C.cache.get(en);
    let out;
    for (const t of C.tpl){
      if (t.key && en.indexOf(t.key) < 0) continue;
      const m = t.re.exec(en); if (!m) continue;
      const val = []; t.order.forEach((ix, j) => { val[ix] = m[j + 1]; });
      out = t.v.replace(/\{(\d+)\}/g, (s, d) => val[+d] !== undefined ? val[+d] : '');
      break;
    }
    if (C.cache.size > 4000) C.cache.clear();
    C.cache.set(en, out);
    return out;
  },
  // по русскому тексту (если английского нет под рукой)
  getRu(L, ru){
    if (typeof ru !== 'string' || typeof V8X_RU === 'undefined') return undefined;
    const C = this.C.__ru || (this.C.__ru = this.build(V8X_RU));
    let en = C.map.get(ru);
    if (en === undefined) for (const t of C.tpl){ const m = t.re.exec(ru); if (!m){ continue; } const val = []; t.order.forEach((ix, j) => { val[ix] = m[j + 1]; }); en = t.v.replace(/\{(\d+)\}/g, (s, d) => val[+d] !== undefined ? val[+d] : ''); break; }
    return en === undefined ? undefined : this.get(L, en);
  },
  // ===== Вариант 1: поиск по en внутри tr. Вызывать СРАЗУ после i18n.js (до v76_factions.js, который
  // запоминает tr в FAC76.tr0), иначе вызовы T82 → FAC76.tr0 обойдут обёртку.
  // Переводы v7.9 не перебиваются: словарь берётся только когда tr вернул английский (перевода нет)
  // или когда vi/he не переданы (A84/T85/X.L передают en вместо vi/he).
  hookTr(){
    if (this.hooked || typeof tr !== 'function') return;
    this.hooked = true;
    const tr0 = tr, self = this;
    const pick = (L, ru, en, vi, he, base) => {
      if (L === 'vi'){ if (self.VI_FULL){ const f = V8X_DICT.vi_full[en]; if (f !== undefined) return f; } if (vi === undefined || vi === en){ const t = self.get('vi', en); if (t !== undefined) return t; } return base; }
      if (L === 'he'){ if (he === undefined || he === en){ if (self.HE_OVER_AUTO || base === en){ const t = self.get('he', en); if (t !== undefined) return t; } } return base; }
      if (base === en || base === ru || base === undefined){ const t = self.get(L, en); if (t !== undefined) return t; }   // v7.8-tr для незнакомого языка отдаёт ru
      return base;
    };
    tr = function(ru, en, vi, he){
      const base = tr0.apply(this, arguments);
      const L = self.code(); if (!L || L === 'ru' || L === 'en' || typeof en !== 'string') return base;
      return pick(L, ru, en, vi, he, base);
    };
    if (typeof N2 === 'function'){ const n0 = N2; N2 = function(p){ const base = n0.apply(this, arguments); const L = self.code(); if (!p || !L || L === 'ru' || L === 'en') return base; return pick(L, p[0], p[1], p[2], p[3], base); }; }
  },
  // ===== Вариант 2а: если tr в v7.9 принимает языки ПОЗИЦИОННО, например tr(ru, en, vi, he, uz, tg, zh, es, pt):
  // дозаполнить недостающие аргументы из словаря и вызвать исходный tr. order — порядок аргументов в v7.9.
  // Как и hookTr, ставить сразу после i18n.js (до v76_factions.js). vi/he, совпадающие с en (A84/T85/X.L), тоже заменяются.
  hookArgs(order){
    if (this.hooked || typeof tr !== 'function') return;
    this.hooked = true;
    const tr0 = tr, self = this;
    order = order || ['ru', 'en', 'vi', 'he', 'uz', 'tg', 'zh', 'es', 'pt-BR'];
    const fillA = a => {
      const en = a[1]; if (typeof en !== 'string') return a;
      for (let i = 2; i < order.length; i++){
        const L = self.code(order[i]);
        if (L === 'vi' && self.VI_FULL && V8X_DICT.vi_full[en] !== undefined){ a[i] = V8X_DICT.vi_full[en]; continue; }
        if (a[i] === undefined || a[i] === en){ const t = self.get(L, en); if (t !== undefined) a[i] = t; }
      }
      return a;
    };
    tr = function(){ return tr0.apply(this, fillA(Array.prototype.slice.call(arguments))); };
    if (typeof N2 === 'function'){ const n0 = N2; N2 = function(p){ return Array.isArray(p) ? n0.call(this, fillA(p.slice())) : n0.apply(this, arguments); }; }
  },
  // ===== Вариант 2б: предварительно заполнить словари v7.9 (если v7.9 хранит переводы как { en: текст } на язык).
  // targets: { uz: UZ79_DICT, tg: TG79_DICT, ... } — имена подставь из v7.9. Существующие ключи не трогаются.
  fill(targets, overwrite){
    const n = {};
    for (const L in targets){
      const D = V8X_DICT[this.code(L)], T = targets[L]; if (!D || !T) continue; n[L] = 0;
      for (const k in D) if (overwrite || T[k] === undefined){ T[k] = D[k]; n[L]++; }
    }
    return n;
  },
  // для иврита: просто влить в HE68_DICT — HE68(en) сразу начнёт отдавать наш перевод
  fillHe(){ if (typeof HE68_DICT === 'undefined') return 0; let n = 0; for (const k in V8X_DICT.he){ HE68_DICT[k] = V8X_DICT.he[k]; n++; } if (typeof HE68C !== 'undefined'){ HE68C.map = null; HE68C.cache.clear(); } return n; },
  // самопроверка в консоли: V8X.selfTest('zh')
  selfTest(L){ const D = V8X_DICT[this.code(L)] || {}; const keys = Object.keys(D); let ok = 0; for (const k of keys) if (this.get(L, k.replace(/\{\d+\}/g, '7')) !== undefined) ok++; return { lang: L, keys: keys.length, matched: ok }; },
};
